// Navigation and field workflows: daily production first, management grouped, permissions explicit.
const preferredNavigation=[
  ['home','Accueil'],['planning','Planning'],['personal','Mon espace'],['jobs','Chantiers'],['people','Personnel & équipes'],['quotes','Devis'],
  ['gallery','Réalisations'],['fleet','Biens & matériel'],['accounting','Comptabilité'],
  ['actions','Tâches générales'],['documents','Documents'],
  ['permissions','Droits d’accès'],['company','Entreprise']
];
tabs2.splice(0,tabs2.length,...preferredNavigation.filter(([key])=>['home','personal'].includes(key)||tabs2.some(([existing])=>existing===key)));

function managementTabs(active){return `<div class="management-tabs" role="navigation" aria-label="Comptabilité et rentabilité"><button class="${active==='accounting'?'selected':''}" onclick="navigate('accounting')">Comptabilité</button><button class="${active==='profitability'?'selected':''}" onclick="navigate('profitability')">Rentabilité des chantiers</button></div>`}
const accountingBeforeGrouping=accountingView;
accountingView=function(){return managementTabs('accounting')+accountingBeforeGrouping()};
const profitabilityBeforeGrouping=profitabilityView;
profitabilityView=function(){return managementTabs('profitability')+profitabilityBeforeGrouping()};

// Fast, complete time entry from the chantier list.
function quickTimeForm(jobId=0){const active=activeJobsForPlanning(),selected=active.find(j=>j.id===jobId)||active[0],assignment=assignments.find(a=>a.job===selected?.id),team=teams.find(t=>t.id===assignment?.team)||teams[0];modal('Encoder les heures du chantier',`<form onsubmit="saveQuickTime(event)"><div class="form-two"><label>Chantier<select name="job" required>${active.map(j=>`<option value="${j.id}" ${j.id===selected?.id?'selected':''}>${esc(j.name)} · ${esc(j.town)}</option>`).join('')}</select></label><label>Équipe<select name="team" required>${teams.map(t=>`<option value="${t.id}" ${t.id===team?.id?'selected':''}>${esc(t.name)} · ${t.members.length} personnes</option>`).join('')}</select></label><label>Date<input name="date" type="date" required value="${reference}"></label><label>Arrivée<input name="arrival" type="time" required value="07:30"></label><label>Départ<input name="departure" type="time" required value="16:15"></label></div><label>Remarque du jour<input name="note" maxlength="250" placeholder="Travaux réalisés, météo, attente de matériel…"></label><p class="notice"><strong>Les heures sont enregistrées pour chaque membre de l’équipe.</strong> Les pauses définies par l’entreprise seront déduites automatiquement.</p><p id="quickTimeError" class="form-error" role="alert"></p><div class="modal-actions"><button class="btn primary">Enregistrer les heures</button></div></form>`)}
function saveQuickTime(event){event.preventDefault();const f=new FormData(event.target),job=jobs.find(j=>j.id===+f.get('job')),team=teams.find(t=>t.id===+f.get('team')),date=f.get('date'),arrival=f.get('arrival'),departure=f.get('departure');if(!job||!team)return;if(departure<=arrival){document.querySelector('#quickTimeError').textContent='L’heure de départ doit être postérieure à l’arrivée.';return}if(job.timeEntries.some(e=>e.team===team.id&&e.date===date)){document.querySelector('#quickTimeError').textContent='Cette équipe possède déjà un pointage pour ce chantier à cette date.';return}job.timeEntries.push({id:Date.now(),team:team.id,people:[...team.members],date,arrival,departure,note:f.get('note').trim()});closeModal();render();toast(`Heures enregistrées pour ${team.members.length} personne(s).`)}

const jobsBeforeQuickTime=jobsView;
jobsView=function(){return jobsBeforeQuickTime()};

function todayTeamAssignments(){return assignments.filter(a=>a.date===reference&&!isArchivedJob(jobs.find(j=>j.id===a.job)))}
function teamDayEntry(assignment){return jobs.find(j=>j.id===assignment.job)?.timeEntries?.find(entry=>entry.team===assignment.team&&entry.date===reference)}
function teamClockForm(jobId,teamId){const job=jobs.find(j=>j.id===jobId),team=teams.find(t=>t.id===teamId),assignment=assignments.find(a=>a.date===reference&&a.job===jobId&&a.team===teamId),now=new Date().toLocaleTimeString('fr-BE',{hour:'2-digit',minute:'2-digit'});if(!job||!team)return;modal('Pointer l’arrivée',`<form onsubmit="saveTeamClockIn(event,${jobId},${teamId})"><div class="clock-confirm"><span class="clock-icon">▶</span><div><small>${esc(team.name)}</small><strong>${esc(job.name)}</strong><span>${(assignment?.people||team.members).map(id=>getPerson(id)?.name).filter(Boolean).join(' · ')}</span></div><time>${now}</time></div><label>Heure d’arrivée<input name="arrival" type="time" required value="${now}"></label><label>Remarque facultative<input name="note" maxlength="250" placeholder="Retard fournisseur, météo, accès…"></label><p class="notice">Le pointage sera créé pour toute l’équipe prévue aujourd’hui.</p><div class="modal-actions"><button class="btn primary">Confirmer l’arrivée</button></div></form>`)}
function saveTeamClockIn(event,jobId,teamId){event.preventDefault();const f=new FormData(event.target),job=jobs.find(j=>j.id===jobId),team=teams.find(t=>t.id===teamId),assignment=assignments.find(a=>a.date===reference&&a.job===jobId&&a.team===teamId);if(!job||!team)return;if(teamDayEntry({job:jobId,team:teamId}))return toast('Cette équipe possède déjà un pointage aujourd’hui.');job.timeEntries.push({id:Date.now(),team:teamId,people:[...(assignment?.people||team.members)],date:reference,arrival:f.get('arrival'),departure:'',note:f.get('note').trim()});closeModal();render();toast('Arrivée de l’équipe enregistrée.')}
function teamClockOutForm(jobId,entryId){const job=jobs.find(j=>j.id===jobId),entry=job?.timeEntries.find(e=>e.id===entryId),team=teams.find(t=>t.id===entry?.team),now=new Date().toLocaleTimeString('fr-BE',{hour:'2-digit',minute:'2-digit'});if(!job||!entry)return;modal('Pointer le départ',`<form onsubmit="saveTeamClockOut(event,${jobId},${entryId})"><div class="clock-confirm departure"><span class="clock-icon">■</span><div><small>${esc(team?.name||'Équipe')}</small><strong>${esc(job.name)}</strong><span>Arrivée enregistrée à ${esc(entry.arrival)}</span></div><time>${now}</time></div><label>Heure de départ<input name="departure" type="time" required value="${now}"></label><label>Remarque de fin de journée<input name="note" maxlength="250" placeholder="Travaux terminés, matériel à prévoir…"></label><p id="clockOutError" class="form-error" role="alert"></p><div class="modal-actions"><button class="btn primary">Confirmer le départ</button></div></form>`)}
function saveTeamClockOut(event,jobId,entryId){event.preventDefault();const f=new FormData(event.target),job=jobs.find(j=>j.id===jobId),entry=job?.timeEntries.find(e=>e.id===entryId),departure=f.get('departure');if(!entry)return;if(departure<=entry.arrival){document.querySelector('#clockOutError').textContent='Le départ doit être postérieur à l’arrivée.';return}entry.departure=departure;if(f.get('note').trim())entry.note=[entry.note,f.get('note').trim()].filter(Boolean).join(' · ');closeModal();render();toast('Départ de l’équipe enregistré. Les heures sont calculées.')}
function homeTimeClock(){const list=todayTeamAssignments();return `<section class="home-clock"><div class="home-clock-head"><div><p class="eyebrow">POINTAGE DU JOUR</p><h1>Arrivée et départ du chantier</h1><span>L’équipe et le chantier viennent directement du planning.</span></div><button class="link" onclick="quickTimeForm()">Corriger ou encoder manuellement</button></div><div class="home-clock-grid">${list.map(assignment=>{const team=teams.find(t=>t.id===assignment.team),job=jobs.find(j=>j.id===assignment.job),vehicle=fleet.find(v=>v.id===assignment.vehicle),entry=teamDayEntry(assignment),names=(assignment.people||team?.members||[]).map(id=>getPerson(id)?.name?.split(' ')[0]).filter(Boolean).join(' · ');return `<article class="clock-card ${entry?.departure?'complete':entry?'running':''}"><div><span class="badge">${esc(team?.name||'Équipe')}</span><h2>${esc(job?.name||'Chantier')}</h2><p>${esc(job?.town||'')} · ${esc(vehicle?.name||'Véhicule à définir')}</p><small>${esc(names)}</small></div>${!entry?`<button class="btn primary clock-button" onclick="teamClockForm(${assignment.job},${assignment.team})">▶ Pointer l’arrivée</button>`:!entry.departure?`<div class="clock-running"><span>Arrivée · ${esc(entry.arrival)}</span><button class="btn primary clock-button" onclick="teamClockOutForm(${assignment.job},${entry.id})">■ Pointer le départ</button></div>`:`<div class="clock-complete"><strong>✓ Journée pointée</strong><span>${esc(entry.arrival)} → ${esc(entry.departure)}</span></div>`}</article>`}).join('')||'<div class="empty">Aucune équipe n’est affectée aujourd’hui. Le patron peut préparer la journée dans le planning.</div>'}</div></section>`}
const planningBeforeHomeClock=planning;
function homeNews(){const list=[...newsItems].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3);return `<section class="home-news"><div class="panel-head"><div><p class="eyebrow">ACTUALITÉS & RÈGLES</p><h2>À connaître dans l’entreprise</h2><span>Informations utiles au patron comme aux équipes.</span></div><button class="btn" onclick="navigate('news')">Voir toutes les actualités</button></div><div class="home-news-grid">${list.map(item=>`<article><div><span class="badge">${esc(item.category)}</span><time>${fullDate(item.date)}</time></div><h3>${esc(item.title)}</h3><p>${esc(item.summary)}</p><button class="link" onclick="navigate('news')">Lire et voir la source →</button></article>`).join('')}</div><p class="help-line">Les informations réelles devront toujours afficher leur source officielle et leur date de vérification.</p></section>`}
function workflowHomeOverview(){return homeTimeClock()+planningBeforeHomeClock()+homeNews()}

// An alert has a dossier and a recipient: the two are deliberately independent.
reminderForm=function(id='',type='company',linkId=0){const r=reminders.find(item=>item.id===id)||{title:'',date:reference,kind:'Administratif',owner:'',linkType:type,linkId,note:''},inferred=people.find(p=>p.id===r.assigneeId||p.name===r.owner),assigneeValue=inferred?`person:${inferred.id}`:'owner:0';modal(id?'Modifier l’alerte':'Nouvelle alerte',`<form onsubmit="saveAssignedReminder(event,'${jsString(id)}')"><label>Intitulé<input name="title" required maxlength="150" value="${esc(r.title)}"></label><div class="form-two"><label>Catégorie<select name="kind">${[...new Set(['Chantier','Matériel','Formation','Permis','Administratif','Rendez-vous',r.kind])].map(k=>`<option ${k===r.kind?'selected':''}>${esc(k)}</option>`).join('')}</select></label><label>Date<input name="date" type="date" required value="${r.date}"></label></div><label>Destinataire de l’alerte<select name="assignee" required><option value="owner:0" ${assigneeValue==='owner:0'?'selected':''}>Moi · Patron</option>${people.map(p=>`<option value="person:${p.id}" ${assigneeValue===`person:${p.id}`?'selected':''}>${esc(p.name)} · ${esc(p.role)}</option>`).join('')}</select></label><label>Dossier concerné<select name="link"><option value="company:0">Entreprise</option><optgroup label="Personnel">${people.map(p=>`<option value="person:${p.id}" ${r.linkType==='person'&&r.linkId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</optgroup><optgroup label="Chantiers">${jobs.map(j=>`<option value="job:${j.id}" ${r.linkType==='job'&&r.linkId===j.id?'selected':''}>${esc(j.name)}</option>`).join('')}</optgroup><optgroup label="Biens & véhicules">${assets.map(a=>`<option value="asset:${a.id}" ${r.linkType==='asset'&&r.linkId===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</optgroup></select></label><label>Consigne<textarea name="note" rows="4" maxlength="1000">${esc(r.note||'')}</textarea></label><p class="notice">L’alerte apparaîtra dans « Mon espace » du destinataire jusqu’à ce qu’elle soit traitée.</p><div class="modal-actions"><button class="btn primary">Enregistrer et attribuer</button></div></form>`)};
function saveAssignedReminder(event,id){event.preventDefault();const f=new FormData(event.target),[assigneeType,assigneeRaw]=f.get('assignee').split(':'),assigneeId=+assigneeRaw,[linkType,linkRaw]=f.get('link').split(':'),person=people.find(p=>p.id===assigneeId),owner=assigneeType==='owner'?(company.manager||'Patron'):(person?.name||'À attribuer'),data={title:f.get('title').trim(),date:f.get('date'),kind:f.get('kind'),owner,assigneeType,assigneeId:assigneeType==='person'?assigneeId:0,assigneeName:owner,note:f.get('note').trim(),linkType,linkId:+linkRaw};if(!data.title)return;let reminder=reminders.find(r=>r.id===id);if(reminder)Object.assign(reminder,data);else reminders.push({id:'reminder-'+crypto.randomUUID(),...data,state:'todo',completedAt:''});closeModal();render();toast(`Alerte attribuée à ${owner}.`)}
openReminderDossier=function(id){const reminder=reminders.find(r=>r.id===id);if(!reminder)return;if(reminder.linkType==='asset')showAsset(reminder.linkId);else if(reminder.linkType==='person')personForm(reminder.linkId);else if(reminder.linkType==='job')showJob(reminder.linkId);else{closeModal();navigate('company')}};

let personalPreviewId=6;
function personalAlerts(person){return reminders.filter(r=>r.state!=='done'&&(r.assigneeId===person.id||(!r.assigneeId&&r.owner===person.name))).sort((a,b)=>a.date.localeCompare(b.date))}
function personalHours(person){const monday=mondayOf(reference),sunday=isoDay(monday,6);return jobs.reduce((total,job)=>total+job.timeEntries.filter(entry=>entry.date>=monday&&entry.date<=sunday&&entry.people?.includes(person.id)).reduce((sum,entry)=>sum+netMinutes(entry)/60,0),0)}
function personalView(){const person=getPerson(personalPreviewId)||people[0],today=assignments.find(a=>a.date===reference&&(a.people||teams.find(t=>t.id===a.team)?.members||[]).includes(person.id)),job=jobs.find(j=>j.id===today?.job),team=teams.find(t=>t.id===today?.team),vehicle=fleet.find(v=>v.id===today?.vehicle),alerts=personalAlerts(person),permits=person.hr?.permits||[],documents=allDocuments().filter(d=>d.link==='person'&&d.linkId===person.id);return `<div class="personal-head"><div>${face(person).replace('class="person-avatar '+person.color+'"','class="person-avatar '+person.color+'" data-person-id="'+esc(person.id)+'"')}<div><p class="eyebrow">MON ESPACE</p><h1>Bonjour ${esc(person.name.split(' ')[0])}</h1><span>${esc(person.role)}</span></div></div><label>Aperçu de démonstration<select onchange="personalPreviewId=+this.value;render()">${people.map(p=>`<option value="${p.id}" ${p.id===person.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label></div><div class="personal-kpis"><div><small>Heures cette semaine</small><strong>${personalHours(person).toFixed(1)} h</strong></div><div><small>Alertes à traiter</small><strong>${alerts.length}</strong></div><div><small>Documents personnels</small><strong>${documents.length}</strong></div><div><small>Téléphone</small><strong>${esc(person.phone||'À renseigner')}</strong></div></div><section class="personal-today"><div><p class="eyebrow">AUJOURD’HUI</p><h2>${job?esc(job.name):'Aucun chantier planifié'}</h2>${job?`<p>${esc(job.address||'Adresse à préciser')}${job.town?' · '+esc(job.town):''}</p><div class="training-tags"><span>${esc(team?.name||'Équipe')}</span><span>${esc(vehicle?.name||'Véhicule à définir')}</span></div>`:'<p>Consultez le planning ou contactez votre chef d’équipe.</p>'}</div><button class="btn primary" onclick="navigate('planning')">Ouvrir le pointage</button></section><div class="personal-columns"><section class="panel"><div class="panel-head"><div><p class="eyebrow">MES ALERTES</p><h2>À faire</h2></div></div>${alerts.length?alerts.map(r=>{const state=reminderState(r);return `<button class="personal-alert" onclick="showReminder('${jsString(r.id)}')"><span><strong>${esc(r.title)}</strong><small>${fullDate(r.date)} · ${esc(r.kind)}</small></span><span class="badge ${state[1]}">${state[0]}</span></button>`}).join(''):'<div class="empty">Aucune alerte attribuée.</div>'}</section><section class="panel"><div class="panel-head"><div><p class="eyebrow">MON DOSSIER</p><h2>Permis & formations</h2></div></div><div class="personal-credentials">${permits.map(p=>`<div><span>✓</span><p><strong>${esc(p.name)}</strong><small>${p.expires?'Échéance à vérifier · '+fullDate(p.expires):'Validité à vérifier'}</small></p></div>`).join('')}${person.training.map(t=>`<div><span>✓</span><p><strong>${esc(t)}</strong><small>Attestation dans Documents</small></p></div>`).join('')}</div></section></div>`}

const renderBeforePersonalSpace=render;
render=function(){if(view!=='personal')return renderBeforePersonalSpace();document.querySelector('#nav').innerHTML=tabs2.map(([value,label])=>`<button class="${view===value?'active':''}" ${view===value?'aria-current="page"':''} onclick="navigate('${value}')">${label}</button>`).join('');document.querySelector('#main').innerHTML=personalView();scheduleSave()};

// Final compact home requested by the field teams.
function openTodayEntries(){return jobs.flatMap(job=>(job.timeEntries||[]).filter(entry=>entry.date===reference&&!entry.departure).map(entry=>({job,entry,team:teams.find(t=>t.id===entry.team)})))}
function compactTerrainHome(){const activeCount=activeJobsForPlanning().length,open=openTodayEntries();return `<div class="home-field-actions"><section class="field-action-strip time-action"><div><p class="eyebrow">POINTAGE TERRAIN</p><h2>Arrivée & départ</h2><span>${open.length?`${open.length} équipe(s) actuellement sur chantier`:`${activeCount} chantier(s) actif(s) · pointez votre arrivée`}</span></div><div>${open.length?'<button class="btn primary" onclick="fieldTimeForm()">■ Pointer le départ</button>':''}<button class="btn ${open.length?'':'primary'}" onclick="fieldArrivalForm()">▶ Pointer l’arrivée</button></div></section><section class="field-action-strip asset-action"><div><p class="eyebrow">BIENS & MATÉRIEL</p><h2>Action rapide</h2><span>Carburant, kilométrage ou problème matériel.</span></div><div><button class="btn primary" onclick="fuelForm()">⛽ Enregistrer un plein</button><button class="btn" onclick="reportAssetIssueForm()">Signaler un problème</button></div></section></div>`}
function fieldArrivalForm(){const active=activeJobsForPlanning(),now=new Date().toLocaleTimeString('fr-BE',{hour:'2-digit',minute:'2-digit'});modal('Pointer l’arrivée',`<form onsubmit="saveFieldArrival(event)"><p class="notice"><strong>Un seul geste le matin.</strong> Choisissez l’équipe et le chantier ; le départ sera proposé automatiquement ce soir.</p><div class="form-two"><label>Équipe<select name="team" required><option value="" selected disabled>Choisir mon équipe…</option>${teams.map(team=>`<option value="${team.id}">${esc(team.name)} · ${team.members.map(id=>getPerson(id)?.name?.split(' ')[0]).filter(Boolean).join(', ')}</option>`).join('')}</select></label><label>Chantier<select name="job" required><option value="" selected disabled>Choisir le chantier…</option>${active.map(job=>`<option value="${job.id}">${esc(job.name)} · ${esc(job.town)}</option>`).join('')}</select></label><label>Heure d’arrivée<input name="arrival" type="time" required value="${now}"></label></div><label>Remarque facultative<input name="note" maxlength="250" placeholder="Retard, météo, accès, matériel…"></label><p id="fieldClockError" class="form-error" role="alert"></p><div class="modal-actions"><button class="btn primary">▶ Confirmer l’arrivée</button></div></form>`)}
function saveFieldArrival(event){event.preventDefault();const f=new FormData(event.target),job=jobs.find(item=>item.id===+f.get('job')),team=teams.find(item=>item.id===+f.get('team'));if(!job||!team)return;if(job.timeEntries.some(entry=>entry.team===team.id&&entry.date===reference&&!entry.departure)){document.querySelector('#fieldClockError').textContent='Cette équipe est déjà pointée sur ce chantier. Utilisez « Pointer le départ ». ';return}job.timeEntries.push({id:Date.now(),team:team.id,people:[...team.members],date:reference,arrival:f.get('arrival'),departure:'',note:f.get('note').trim(),corrections:[]});closeModal();render();toast('Arrivée enregistrée. Le départ restera disponible ce soir.')}
function fieldTimeForm(){const open=openTodayEntries();modal('Pointer le départ',`<p class="notice"><strong>Choisissez l’équipe qui termine.</strong> Les heures seront calculées à partir de l’arrivée enregistrée.</p><div class="field-open-entries">${open.map(({job,entry,team})=>`<button onclick="teamClockOutForm(${job.id},${entry.id})"><span><strong>${esc(team?.name||'Équipe')}</strong><small>${esc(job.name)} · arrivée à ${esc(entry.arrival)}</small></span><b>■ Départ</b></button>`).join('')||'<div class="empty">Aucune arrivée ouverte aujourd’hui.</div>'}</div><div class="modal-actions"><button class="btn" onclick="fieldArrivalForm()">▶ Pointer une arrivée</button><button class="btn" onclick="timeCorrectionPicker()">Signaler une erreur passée</button></div>`)}
function compactArrivalForm(){const planned=todayTeamAssignments(),first=planned[0];modal('Arrivée sur chantier',`<form onsubmit="saveCompactArrival(event)"><label>Équipe et chantier prévus<select name="assignment" required>${planned.map(a=>{const team=teams.find(t=>t.id===a.team),job=jobs.find(j=>j.id===a.job);return `<option value="${a.id}">${esc(team?.name||'Équipe')} · ${esc(job?.name||'Chantier')}</option>`}).join('')}</select></label><label>Heure d’arrivée<input name="arrival" type="time" required value="${new Date().toLocaleTimeString('fr-BE',{hour:'2-digit',minute:'2-digit'})}"></label><label>Remarque facultative<input name="note" maxlength="250"></label>${!first?'<p class="form-error">Aucune équipe n’est prévue aujourd’hui dans le planning.</p>':''}<div class="modal-actions"><button class="btn primary" ${!first?'disabled':''}>Confirmer l’arrivée</button></div></form>`)}
function saveCompactArrival(event){event.preventDefault();const f=new FormData(event.target),assignment=assignments.find(a=>a.id===+f.get('assignment')),job=jobs.find(j=>j.id===assignment?.job),team=teams.find(t=>t.id===assignment?.team);if(!assignment||!job||!team)return;if(job.timeEntries.some(e=>e.team===team.id&&e.date===reference))return toast('Un pointage existe déjà pour cette équipe aujourd’hui.');job.timeEntries.push({id:Date.now(),team:team.id,people:[...(assignment.people||team.members)],date:reference,arrival:f.get('arrival'),departure:'',note:f.get('note').trim(),corrections:[]});closeModal();render();toast('Arrivée sur chantier enregistrée.')}
function allRecentTimeEntries(){return jobs.flatMap(job=>(job.timeEntries||[]).filter(e=>e.date<=reference).map(entry=>({job,entry,team:teams.find(t=>t.id===entry.team)}))).sort((a,b)=>b.entry.date.localeCompare(a.entry.date)).slice(0,40)}
function timeCorrectionPicker(){const rows=allRecentTimeEntries();modal('Signaler une erreur de pointage',`<div class="correction-picker">${rows.map(({job,entry,team})=>`<button onclick="timeCorrectionForm(${job.id},${entry.id})"><span><strong>${esc(job.name)}</strong><small>${fullDate(entry.date)} · ${esc(team?.name||'Équipe')}</small></span><b>${esc(entry.arrival)} → ${esc(entry.departure||'en cours')}</b></button>`).join('')||'<div class="empty">Aucun pointage à corriger.</div>'}</div>`)}
function timeCorrectionForm(jobId,entryId){const job=jobs.find(j=>j.id===jobId),entry=job?.timeEntries.find(e=>e.id===entryId);if(!entry)return;modal('Demande de correction',`<form onsubmit="saveTimeCorrection(event,${jobId},${entryId})"><div class="form-two"><label>Arrivée corrigée<input name="arrival" type="time" required value="${entry.arrival}"></label><label>Départ corrigé<input name="departure" type="time" value="${entry.departure||''}"></label></div><label>Pourquoi faut-il corriger ?<textarea name="reason" rows="4" required maxlength="500" placeholder="Pointé trop tôt, oubli de départ, mauvais chantier…"></textarea></label><p class="notice">L’heure originale restera dans l’historique. Une personne autorisée validera la correction.</p><div class="modal-actions"><button class="btn primary">Envoyer la demande</button></div></form>`)}
function saveTimeCorrection(event,jobId,entryId){event.preventDefault();const f=new FormData(event.target),job=jobs.find(j=>j.id===jobId),entry=job?.timeEntries.find(e=>e.id===entryId);if(!entry)return;entry.corrections??=[];entry.corrections.push({id:Date.now(),requestedAt:new Date().toISOString(),requestedBy:'Utilisateur connecté',original:{arrival:entry.arrival,departure:entry.departure},proposed:{arrival:f.get('arrival'),departure:f.get('departure')},reason:f.get('reason').trim(),status:'À valider'});closeModal();render();toast('Demande de correction envoyée et ancienne heure conservée.')}
function approveTimeCorrection(jobId,entryId,correctionId,approved){const entry=jobs.find(j=>j.id===jobId)?.timeEntries.find(e=>e.id===entryId),correction=entry?.corrections?.find(c=>c.id===correctionId);if(!correction)return;if(approved){entry.arrival=correction.proposed.arrival;entry.departure=correction.proposed.departure;correction.status='Acceptée'}else correction.status='Refusée';correction.reviewedAt=new Date().toISOString();correction.reviewedBy='Patron';render();toast(approved?'Pointage corrigé, historique conservé.':'Demande de correction refusée.')}

// One alert can target people, teams, or both. Recipients are deduplicated.
reminderForm=function(id='',type='company',linkId=0){const r=reminders.find(item=>item.id===id)||{title:'',date:reference,kind:'Administratif',recipientIds:[],linkType:type,linkId,note:''},existingIds=r.recipientIds?.length?r.recipientIds:(r.assigneeId?[r.assigneeId]:people.filter(p=>p.name===r.owner).map(p=>p.id));modal(id?'Modifier l’alerte':'Nouvelle alerte',`<form onsubmit="saveMultiReminder(event,'${jsString(id)}')"><label>Intitulé<input name="title" required maxlength="150" value="${esc(r.title)}"></label><div class="form-two"><label>Catégorie<select name="kind">${[...new Set(['Chantier','Matériel','Formation','Permis','Administratif','Rendez-vous',r.kind])].map(k=>`<option ${k===r.kind?'selected':''}>${esc(k)}</option>`).join('')}</select></label><label>Date<input name="date" type="date" required value="${r.date}"></label></div><p class="form-section-title">Prévenir une ou plusieurs équipes</p><div class="recipient-teams">${teams.map(team=>`<label><input type="checkbox" name="recipientTeam" value="${team.id}" ${team.members.every(id=>existingIds.includes(id))?'checked':''}><span><strong>${esc(team.name)}</strong><small>${team.members.length} personnes</small></span></label>`).join('')}</div><p class="form-section-title">Ajouter des personnes individuellement</p><div class="check-people compact-recipients">${people.map(p=>`<label><input type="checkbox" name="recipient" value="${p.id}" ${existingIds.includes(p.id)?'checked':''}>${face(p)}<span><strong>${esc(p.name)}</strong><small>${esc(p.role)}</small></span></label>`).join('')}</div><label>Dossier concerné<select name="link"><option value="company:0">Entreprise</option><optgroup label="Personnel">${people.map(p=>`<option value="person:${p.id}" ${r.linkType==='person'&&r.linkId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</optgroup><optgroup label="Chantiers">${jobs.map(j=>`<option value="job:${j.id}" ${r.linkType==='job'&&r.linkId===j.id?'selected':''}>${esc(j.name)}</option>`).join('')}</optgroup><optgroup label="Biens & véhicules">${assets.map(a=>`<option value="asset:${a.id}" ${r.linkType==='asset'&&r.linkId===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</optgroup></select></label><label>Consigne<textarea name="note" rows="3" maxlength="1000">${esc(r.note||'')}</textarea></label><p id="recipientError" class="form-error"></p><div class="modal-actions"><button class="btn primary">Enregistrer et prévenir</button></div></form>`)};
function saveMultiReminder(event,id){event.preventDefault();const f=new FormData(event.target),ids=new Set(f.getAll('recipient').map(Number));f.getAll('recipientTeam').map(Number).forEach(teamId=>teams.find(t=>t.id===teamId)?.members.forEach(personId=>ids.add(personId)));if(!ids.size){document.querySelector('#recipientError').textContent='Choisissez au moins une personne ou une équipe.';return}const recipientIds=[...ids],recipientNames=recipientIds.map(id=>getPerson(id)?.name).filter(Boolean),[linkType,linkRaw]=f.get('link').split(':'),data={title:f.get('title').trim(),date:f.get('date'),kind:f.get('kind'),owner:recipientNames.join(', '),recipientIds,recipientNames,note:f.get('note').trim(),linkType,linkId:+linkRaw};if(!data.title)return;let reminder=reminders.find(r=>r.id===id);if(reminder)Object.assign(reminder,data);else reminders.push({id:'reminder-'+crypto.randomUUID(),...data,state:'todo',completedAt:''});closeModal();render();toast(`Alerte envoyée à ${recipientIds.length} personne(s).`)}
personalAlerts=function(person){return reminders.filter(r=>r.state!=='done'&&((r.recipientIds||[]).includes(person.id)||r.assigneeId===person.id||(!(r.recipientIds||[]).length&&!r.assigneeId&&r.owner===person.name))).sort((a,b)=>a.date.localeCompare(b.date))};

let calendarYear=2026,companyEvents=[];
function easterSunday(year){const a=year%19,b=Math.floor(year/100),c=year%100,d=Math.floor(b/4),e=b%4,f=Math.floor((b+8)/25),g=Math.floor((b-f+1)/3),h=(19*a+b-d-g+15)%30,i=Math.floor(c/4),k=c%4,l=(32+2*e+2*i-h-k)%7,m=Math.floor((a+11*h+22*l)/451),month=Math.floor((h+l-7*m+114)/31)-1,day=(h+l-7*m+114)%31+1;return new Date(Date.UTC(year,month,day))}
function isoDate(date){return date.toISOString().slice(0,10)}
function belgianLegalHolidays(year){const easter=easterSunday(year),after=days=>isoDate(new Date(easter.getTime()+days*86400000));return [[`${year}-01-01`,"Jour de l’an"],[after(1),'Lundi de Pâques'],[`${year}-05-01`,'Fête du Travail'],[after(39),'Ascension'],[after(50),'Lundi de Pentecôte'],[`${year}-07-21`,'Fête nationale'],[`${year}-08-15`,'Assomption'],[`${year}-11-01`,'Toussaint'],[`${year}-11-11`,'Armistice'],[`${year}-12-25`,'Noël']]}
function ensureCompanyEvents(year=calendarYear){if(company.blankWorkspace)return;belgianLegalHolidays(year).forEach(([date,title],index)=>{const source=`legal-${year}-${index}`;if(!companyEvents.some(e=>e.source===source))companyEvents.push({id:source,source,date,title,type:'Jour férié',visibility:'Toute l’entreprise',official:true,note:['2026-08-15','2026-11-01'].includes(date)?'Le jour de remplacement doit être confirmé dans le règlement de travail de l’entreprise.':'Jour férié légal belge.'})})}
ensureCompanyEvents();
function sharedCalendarEvents(){ensureCompanyEvents(calendarYear);const generated=[];assets.filter(a=>a.vehicle?.inspection).forEach(a=>generated.push({id:'inspection-'+a.id,date:a.vehicle.inspection,title:'Contrôle technique · '+a.name,type:'Véhicule',visibility:'Toute l’entreprise'}));people.forEach(p=>(p.training||[]).slice(0,1).forEach((training,i)=>{const matching=reminders.find(r=>r.linkType==='person'&&r.linkId===p.id&&r.kind==='Formation');if(matching)generated.push({id:'training-'+p.id+'-'+i,date:matching.date,title:training+' · '+p.name,type:'Formation',visibility:'Toute l’entreprise'})}));reminders.filter(r=>r.state!=='done'&&r.date&&r.linkType!=='asset'&&['Formation','Permis','Chantier'].includes(r.kind)).forEach(r=>generated.push({id:'shared-reminder-'+r.id,date:r.date,title:r.title,type:r.kind==='Formation'?'Formation':'Événement entreprise',visibility:'Toute l’entreprise',note:r.note||''}));return [...companyEvents,...generated].filter((event,index,list)=>list.findIndex(other=>other.id===event.id)===index)}
function eventColor(type){return type==='Jour férié'?'holiday':type==='Repos construction'?'construction':type==='Formation'?'training':type==='Véhicule'?'vehicle':'manual'}
function annualMonth(year,month){const first=new Date(year,month,1),count=new Date(year,month+1,0).getDate(),offset=(first.getDay()+6)%7,events=sharedCalendarEvents().filter(e=>e.date?.startsWith(`${year}-${String(month+1).padStart(2,'0')}`));return `<article class="annual-month"><h3>${first.toLocaleDateString('fr-BE',{month:'long'})}</h3><div class="month-week"><span>L</span><span>M</span><span>M</span><span>J</span><span>V</span><span>S</span><span>D</span></div><div class="month-days">${Array.from({length:offset},()=>'<i></i>').join('')}${Array.from({length:count},(_,i)=>{const day=i+1,date=`${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`,dayEvents=events.filter(e=>e.date===date);return `<button class="${dayEvents.length?'has-event':''}" onclick="calendarDay('${date}')"><span>${day}</span>${dayEvents.slice(0,3).map(e=>`<b class="${eventColor(e.type)}" title="${esc(e.title)}"></b>`).join('')}</button>`}).join('')}</div></article>`}
function companyCalendar(){return `<section class="company-calendar"><div class="panel-head"><div><p class="eyebrow">CALENDRIER PARTAGÉ</p><h2>L’année de l’entreprise</h2><span>Congés, formations, contrôles et événements visibles par toute l’équipe.</span></div><div class="calendar-controls"><button class="btn square" onclick="calendarYear--;render()">‹</button><strong>${calendarYear}</strong><button class="btn square" onclick="calendarYear++;render()">›</button><button class="btn primary" onclick="companyEventForm()">+ Événement</button></div></div><div class="calendar-legend"><span><i class="holiday"></i>Jour férié légal</span><span><i class="construction"></i>Repos construction</span><span><i class="training"></i>Formation</span><span><i class="vehicle"></i>Véhicule</span><span><i class="manual"></i>Ajout manuel</span></div><div class="annual-calendar">${Array.from({length:12},(_,month)=>annualMonth(calendarYear,month)).join('')}</div><p class="notice"><strong>Jours fériés :</strong> les 10 jours fériés légaux belges sont générés automatiquement pour chaque année. <strong>CP124 :</strong> les congés du bâtiment, fermetures collectives et jours de remplacement restent saisis et confirmés par l’entreprise.</p></section>`}
function calendarDay(date){const events=sharedCalendarEvents().filter(e=>e.date===date);modal('Calendrier · '+fullDate(date),`${events.map(e=>`<div class="calendar-event"><span class="event-dot ${eventColor(e.type)}"></span><div><strong>${esc(e.title)}</strong><small>${esc(e.type)} · ${esc(e.visibility||'Toute l’entreprise')}</small><p>${esc(e.note||'')}</p></div>${e.official?'':'<button class="link" onclick="companyEventForm(\''+e.id+'\')">Modifier</button>'}</div>`).join('')||'<div class="empty">Aucun événement ce jour.</div>'}<div class="modal-actions"><button class="btn primary" onclick="companyEventForm('', '${date}')">+ Ajouter ce jour</button></div>`)}
function companyEventForm(id='',date=reference){const event=companyEvents.find(e=>e.id===id)||{date,title:'',type:'Événement entreprise',note:''};modal(id?'Modifier l’événement':'Nouvel événement partagé',`<form onsubmit="saveCompanyEvent(event,'${jsString(id)}')"><div class="form-two"><label>Date<input name="date" type="date" required value="${event.date}"></label><label>Type<select name="type">${['Événement entreprise','Repos construction','Formation','Véhicule','Fermeture'].map(type=>`<option ${type===event.type?'selected':''}>${type}</option>`).join('')}</select></label></div><label>Intitulé<input name="title" required maxlength="150" value="${esc(event.title)}"></label><label>Précision<textarea name="note" rows="3" maxlength="500">${esc(event.note||'')}</textarea></label><p class="notice">Cet événement sera visible par toute l’entreprise.</p><div class="modal-actions"><button class="btn primary">Enregistrer</button></div></form>`)}
function saveCompanyEvent(event,id){event.preventDefault();const f=new FormData(event.target),data={date:f.get('date'),title:f.get('title').trim(),type:f.get('type'),note:f.get('note').trim(),visibility:'Toute l’entreprise'};if(!data.title)return;const existing=companyEvents.find(e=>e.id===id);if(existing)Object.assign(existing,data);else companyEvents.push({id:'event-'+crypto.randomUUID(),...data});closeModal();render();toast('Événement ajouté au calendrier partagé.')}
const snapshotBeforeSharedCalendar=workspaceSnapshot;
workspaceSnapshot=function(){const state=JSON.parse(snapshotBeforeSharedCalendar());state.companyEvents=companyEvents;return JSON.stringify(state)};
const restoreBeforeSharedCalendar=restoreWorkspace;
restoreWorkspace=function(state){restoreBeforeSharedCalendar(state);companyEvents=Array.isArray(state.companyEvents)?state.companyEvents:[];ensureCompanyEvents()};

// Replace the oversized clock with the two compact field-action strips.
workflowHomeOverview=function(){return compactTerrainHome()+planningBeforeHomeClock()+homeNews()+companyCalendar()};

// Payment delays: only overdue invoices appear here.
function overdueInvoices(){return accountingData.customerInvoices.filter(invoice=>invoice.status!=='Payée'&&invoice.due<reference).sort((a,b)=>a.due.localeCompare(b.due))}
function paymentDelayView(){const list=overdueInvoices();return `<section class="panel payment-delays"><div class="panel-head"><div><p class="eyebrow">SUIVI CLIENTS</p><h2>Retards de paiement <span class="count">${list.length}</span></h2></div></div>${list.length?`<div class="data-table"><table><thead><tr><th>Facture / client</th><th>Chantier</th><th>Retard</th><th>Reste dû</th><th>Dernier rappel</th><th></th></tr></thead><tbody>${list.map(invoice=>{const days=Math.max(1,Math.floor((new Date(reference)-new Date(invoice.due))/86400000)),history=invoice.reminderHistory||[],last=history.at(-1);return `<tr><td><strong>${esc(invoice.ref)}</strong><small>${esc(invoice.client)}</small></td><td>${esc(jobs.find(j=>j.id===invoice.job)?.name||'—')}</td><td><span class="badge red">${days} jour(s)</span></td><td><strong>${money(invoice.amount)}</strong></td><td>${last?fullDate(last.date)+' · '+esc(last.by):'Aucun rappel'}</td><td><button class="btn" onclick="sendPaymentReminder(${invoice.id})">Envoyer un rappel</button><button class="link" onclick="markInvoicePaid(${invoice.id})">Marquer payée</button></td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty">Aucune facture en retard.</div>'}</section>`}
function sendPaymentReminder(id){const invoice=accountingData.customerInvoices.find(x=>x.id===id);if(!invoice)return;modal('Envoyer un rappel de paiement',`<form onsubmit="confirmPaymentReminder(event,${id})"><p><strong>${esc(invoice.ref)} · ${esc(invoice.client)}</strong><br>${money(invoice.amount)} · échéance ${fullDate(invoice.due)}</p><label>Canal<select name="channel"><option>E-mail</option><option>SMS</option><option>E-mail et SMS</option></select></label><label>Message<textarea name="message" rows="5" required>Bonjour, sauf erreur de notre part, la facture ${esc(invoice.ref)} arrivée à échéance le ${fullDate(invoice.due)} reste ouverte. Merci de nous confirmer le paiement.</textarea></label><p class="notice">Démonstration : l’envoi réel nécessitera la connexion de l’adresse e-mail ou du service SMS de l’entreprise.</p><div class="modal-actions"><button class="btn primary">Confirmer le rappel</button></div></form>`)}
function confirmPaymentReminder(event,id){event.preventDefault();const f=new FormData(event.target),invoice=accountingData.customerInvoices.find(x=>x.id===id);invoice.reminderHistory??=[];invoice.reminderHistory.push({id:Date.now(),date:reference,at:new Date().toISOString(),channel:f.get('channel'),message:f.get('message').trim(),by:'Utilisateur connecté'});closeModal();render();toast('Rappel ajouté à l’historique d’envoi.')}
function markInvoicePaid(id){const invoice=accountingData.customerInvoices.find(x=>x.id===id);if(!invoice)return;invoice.status='Payée';invoice.paidAt=reference;render();toast('Facture marquée comme payée. Les relances sont arrêtées.')}

function ensurePaySlips(){if(globalThis.SOCLE_PRODUCTION||company.blankWorkspace)return;people.forEach((person,index)=>{person.hr??=demoHr();person.hr.paySlips??=[];if(!person.hr.paySlips.length&&['Ouvrier','Employé','Apprenti'].includes(person.category)){['2026-06','2026-07','2026-08'].forEach((period,i)=>person.hr.paySlips.push({id:`demo-slip-${person.id}-${i}`,period,fileName:`Fiche-paie-${period}-${person.name.replaceAll(' ','-')}.pdf`,uploadedAt:`${period}-28T09:00:00`,uploadedBy:'Sophie Bernard',readAt:i<2?`${period}-29T18:00:00`:'',demo:true}))}})}
ensurePaySlips();
const restoreBeforePaySlips=restoreWorkspace;
restoreWorkspace=function(state){restoreBeforePaySlips(state);ensurePaySlips()};
if(!sensitiveAccess.some(item=>item.key==='paySlips'))sensitiveAccess.push({key:'paySlips',label:'Fiches de paie',detail:'Déposer et consulter les fiches de tous les travailleurs'});
for(const profile of ['Administration','Comptable'])if(!accessProfiles[profile].sensitive.includes('paySlips'))accessProfiles[profile].sensitive.push('paySlips');
function paySlipForm(personId=0){modal('Déposer une fiche de paie',`<form onsubmit="savePaySlip(event)"><div class="form-two"><label>Travailleur<select name="person">${people.map(p=>`<option value="${p.id}" ${p.id===personId?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>Mois<input name="period" type="month" required value="2026-09"></label></div><label>Fiche de paie PDF<input name="file" type="file" accept="application/pdf" required></label><p class="notice">Chaque travailleur ne voit que ses propres fiches. Le dépôt est réservé à la paie, à l’administration autorisée et au patron.</p><div class="modal-actions"><button class="btn primary">Déposer dans Mon espace</button></div></form>`)}
function savePaySlip(event){event.preventDefault();const f=new FormData(event.target),person=getPerson(+f.get('person')),file=f.get('file');if(!person||!file?.name)return;person.hr.paySlips??=[];const existing=person.hr.paySlips.find(s=>s.period===f.get('period'));const data={id:existing?.id||'slip-'+crypto.randomUUID(),period:f.get('period'),fileName:file.name,uploadedAt:new Date().toISOString(),uploadedBy:'Utilisateur autorisé',readAt:'',replacedFile:existing?.fileName||''};if(existing)Object.assign(existing,data);else person.hr.paySlips.push(data);closeModal();render();toast('Fiche de paie déposée dans l’espace du travailleur.')}
function payrollDocumentView(){const rows=people.flatMap(person=>(person.hr?.paySlips||[]).map(slip=>({person,slip}))).sort((a,b)=>b.slip.period.localeCompare(a.slip.period)).slice(0,24);return `<section class="panel payroll-documents"><div class="panel-head"><div><p class="eyebrow">DOCUMENTS PERSONNELS</p><h2>Fiches de paie</h2></div><button class="btn primary" onclick="paySlipForm()">+ Déposer une fiche</button></div><div class="data-table"><table><thead><tr><th>Travailleur</th><th>Période</th><th>Document</th><th>Déposé par</th><th>Consultation</th></tr></thead><tbody>${rows.map(({person,slip})=>`<tr><td><strong>${esc(person.name)}</strong></td><td>${esc(slip.period)}</td><td>${esc(slip.fileName)}</td><td>${esc(slip.uploadedBy)}</td><td><span class="badge ${slip.readAt?'green':'warn'}">${slip.readAt?'Consultée':'Non consultée'}</span></td></tr>`).join('')}</tbody></table></div></section>`}
const accountingBeforePaymentAndPayroll=accountingView;
accountingView=function(){return accountingBeforePaymentAndPayroll()+paymentDelayView()+payrollDocumentView()};
const personalBeforePaySlips=personalView;
personalView=function(){const person=getPerson(personalPreviewId)||people[0],slips=[...(person.hr?.paySlips||[])].sort((a,b)=>b.period.localeCompare(a.period));return personalBeforePaySlips()+`<section class="panel my-pay-slips"><div class="panel-head"><div><p class="eyebrow">DOCUMENTS CONFIDENTIELS</p><h2>Mes fiches de paie</h2></div><span class="badge">Moi uniquement</span></div><div class="pay-slip-grid">${slips.map(slip=>`<button onclick="markPaySlipRead(${person.id},'${jsString(slip.id)}')"><span class="folder-icon">${icon('file')}</span><span><strong>${esc(slip.period)}</strong><small>${esc(slip.fileName)}</small></span><span class="badge ${slip.readAt?'green':'warn'}">${slip.readAt?'Consultée':'Nouvelle'}</span></button>`).join('')||'<div class="empty">Aucune fiche de paie disponible.</div>'}</div></section>`}
function markPaySlipRead(personId,id){const slip=getPerson(personId)?.hr?.paySlips?.find(s=>s.id===id);if(!slip)return;slip.readAt||=new Date().toISOString();render();toast('Fiche marquée comme consultée. Le téléchargement réel sera relié au stockage documentaire.')}

function reportAssetIssueForm(){const list=assets.filter(a=>a.group==='vehicles'||a.group==='tools');modal('Signaler un problème matériel',`<form onsubmit="saveAssetIssue(event)"><label>Véhicule ou matériel<select name="asset" required>${list.map(a=>`<option value="${a.id}">${esc(a.name)} · ${esc(a.attached||'Emplacement à préciser')}</option>`).join('')}</select></label><label>Importance<select name="severity"><option>À contrôler</option><option>Réparation nécessaire</option><option>Immobilisé</option></select></label><label>Description<textarea name="description" rows="4" required maxlength="600" placeholder="Expliquez ce qui ne va pas et où se trouve le matériel."></textarea></label><div class="modal-actions"><button class="btn primary">Envoyer le signalement</button></div></form>`)}
function saveAssetIssue(event){event.preventDefault();const f=new FormData(event.target),asset=assets.find(a=>a.id===+f.get('asset')),severity=f.get('severity'),description=f.get('description').trim();if(!asset||!description)return;asset.history??=[];asset.history.push({date:reference,text:`Signalement terrain · ${severity} : ${description}`});if(severity==='Immobilisé'||severity==='Réparation nécessaire'){asset.condition=severity==='Immobilisé'?'En réparation':'À réparer';syncAssetReminder(asset,'repair',reference,'Réparation · '+asset.name,'Réparation')}closeModal();assetCategory=severity==='À contrôler'?'tools':'repairs';navigate('fleet');toast('Signalement ajouté au dossier du matériel.')}

const fleetBeforeFieldActions=fleetView;
fleetView=function(){return `<section class="field-action-strip asset-action"><div><p class="eyebrow">ACTIONS TERRAIN</p><h2>Véhicules & matériel</h2><span>Un plein, un kilométrage ou un problème se signale directement ici.</span></div><div><button class="btn primary" onclick="fuelForm()">⛽ Enregistrer un plein</button><button class="btn" onclick="reportAssetIssueForm()">Signaler un problème</button></div></section>`+fleetBeforeFieldActions()};

// Explicit field permissions complement the broad module permissions.
const fieldPermissions=[
 {key:'logHours',label:'Encoder les heures',detail:'Ajouter les heures de son équipe dans un chantier'},
 {key:'logFuel',label:'Enregistrer un plein',detail:'Kilométrage, litres, montant et ticket du véhicule'},
 {key:'reportAssetIssue',label:'Signaler un problème',detail:'Panne, dégât, outil manquant ou matériel à contrôler'}
];
function fieldDefaults(profile){return {logHours:['Patron','Administration','Chef d’équipe','Ouvrier'].includes(profile),logFuel:['Patron','Chef d’équipe','Ouvrier'].includes(profile),reportAssetIssue:['Patron','Administration','Chef d’équipe','Ouvrier'].includes(profile)}}
const ensureAccessBeforeFieldPermissions=ensureAccessAssignments;
ensureAccessAssignments=function(){const previous=Object.fromEntries(Object.entries(accessAssignments||{}).map(([key,value])=>[key,value.fieldActions]));ensureAccessBeforeFieldPermissions();Object.entries(accessAssignments).forEach(([key,a])=>{const defaults=fieldDefaults(a.profile);a.fieldActions={...defaults,...(previous[key]||a.fieldActions||{})}})};
function toggleFieldPermission(key,permission,enabled){if(key==='owner'||!accessAssignments[key])return;accessAssignments[key].fieldActions??=fieldDefaults(accessAssignments[key].profile);accessAssignments[key].fieldActions[permission]=Boolean(enabled);render();persistServerAccess(key,'Permission terrain enregistrée côté serveur.')}
const permissionsBeforeFieldActions=permissionsView;
permissionsView=function(){ensureAccessAssignments();const base=permissionsBeforeFieldActions(),assignment=accessAssignments[selectedAccessKey],member=accessMembers().find(item=>item.key===selectedAccessKey),locked=selectedAccessKey==='owner'||(!member?.owner&&!member?.serverUserId);const panel=`<section class="panel sensitive-panel field-permission-panel"><div class="panel-head"><div><p class="eyebrow">ACTIONS TERRAIN</p><h2>Ce que cette personne peut enregistrer</h2></div><span class="badge green">Accès opérationnel</span></div><div class="sensitive-grid">${fieldPermissions.map(item=>`<label><span><strong>${esc(item.label)}</strong><small>${esc(item.detail)}</small></span><input type="checkbox" ${assignment.fieldActions?.[item.key]?'checked':''} ${locked?'disabled':''} onchange="toggleFieldPermission('${jsString(selectedAccessKey)}','${jsString(item.key)}',this.checked)"><i aria-hidden="true"></i></label>`).join('')}</div></section>`;return base.replace('<section class="panel sensitive-panel">',panel+'<section class="panel sensitive-panel">')};

// Documents breathe through a two-level classification instead of one long list.
let docSubcategory='Tous';
const documentTree={
 'Entreprise':{description:'Identité, banque, assurances et gestion de la société',children:['Identité légale','Banque & assurances','Administration']},
 'Personnel':{description:'Un dossier documentaire par membre de l’entreprise',children:['Contrats','Permis de conduire','Habilitations','Accidents']},
 'Formations':{description:'Attestations et compétences liées au travail',children:['Sécurité','Technique','Secourisme']},
 'Chantiers':{description:'Plans, métrés, sécurité et pièces d’exécution',children:['Plans & métrés','Sécurité chantier','Autorisations']}
};
function ensurePersonnelDocuments(){if(globalThis.SOCLE_PRODUCTION||company.blankWorkspace)return;people.forEach((person,index)=>{person.hr??=demoHr();person.hr.permits??=[];const fieldWorker=['Ouvrier','Apprenti'].includes(person.category)||/chantier|magasinier/i.test(person.role);if(fieldWorker&&!person.hr.permits.some(p=>p.name==='Permis B'))person.hr.permits.push({name:'Permis B',expires:isoDay('2031-03-15',index*17),kind:'Conduite'});if(/Chef|Gestionnaire|Magasinier/.test(person.role)&&!person.hr.permits.some(p=>p.name==='Permis BE'))person.hr.permits.push({name:'Permis BE',expires:isoDay('2030-06-20',index*19),kind:'Conduite avec remorque'});if(/Marc Legrand/.test(person.name)&&!person.hr.permits.some(p=>p.name==='Permis C'))person.hr.permits.push({name:'Permis C',expires:'2029-11-30',kind:'Poids lourd'});if(fieldWorker&&!person.hr.permits.some(p=>p.name==='Aptitude travail en hauteur'))person.hr.permits.push({name:'Aptitude travail en hauteur',expires:isoDay('2027-02-10',index*11),kind:'Habilitation'})})}
ensurePersonnelDocuments();
const restoreBeforePersonnelDocuments=restoreWorkspace;
restoreWorkspace=function(state){restoreBeforePersonnelDocuments(state);ensurePersonnelDocuments()};

