allDocuments=function(){const list=[
 {id:'company-bce',category:'Entreprise',subcategory:'Identité légale',name:'Extrait de la Banque-Carrefour des Entreprises',type:'Identité légale',owner:company.name,status:'À joindre',date:reference,link:'company',linkId:0},
 {id:'company-vat',category:'Entreprise',subcategory:'Identité légale',name:'Identification TVA',type:'Fiscalité',owner:company.name,status:company.vat?'Référencée':'À compléter',date:reference,link:'company',linkId:0},
 {id:'company-bank',category:'Entreprise',subcategory:'Banque & assurances',name:'Attestation bancaire de l’entreprise',type:'Banque',owner:company.name,status:company.iban?'Référencée':'À joindre',date:reference,link:'company',linkId:0},
 {id:'company-insurance',category:'Entreprise',subcategory:'Banque & assurances',name:'Assurance responsabilité civile entreprise',type:'Assurance',owner:company.name,status:'À vérifier',date:'2027-01-31',link:'company',linkId:0},
 {id:'company-accountant',category:'Entreprise',subcategory:'Administration',name:'Convention avec le bureau comptable',type:'Contrat de service',owner:company.name,status:'Référencée',date:'2026-01-01',link:'company',linkId:0},
 {id:'company-cp124',category:'Entreprise',subcategory:'Administration',name:'Dossier employeur · Commission paritaire 124',type:'Personnel',owner:company.name,status:'Référencé',date:reference,link:'company',linkId:0}
 ];
 people.forEach(person=>{
  list.push({id:`person-${person.id}-contract`,category:'Personnel',subcategory:'Contrats',name:`Contrat de travail · ${person.name}`,type:person.contract,owner:person.name,status:'Référencé',date:person.start,link:'person',linkId:person.id});
  person.training.forEach((training,index)=>list.push({id:`person-${person.id}-training-${index}`,category:'Formations',subcategory:trainingSubcategory(training),name:`Attestation · ${training}`,type:'Formation',owner:person.name,status:'À joindre',date:person.start,link:'person',linkId:person.id}));
  (person.hr?.permits||[]).forEach((permit,index)=>list.push({id:`person-${person.id}-permit-${index}`,category:'Personnel',subcategory:permit.name.startsWith('Permis')?'Permis de conduire':'Habilitations',name:`${permit.name} · ${person.name}`,type:permit.kind||'Permis / habilitation',owner:person.name,status:permit.expires&&permit.expires<reference?'Expiré':'Valide · à vérifier',date:permit.expires||reference,link:'person',linkId:person.id}));
  (person.hr?.accidents||[]).forEach((accident,index)=>list.push({id:`person-${person.id}-accident-${index}`,category:'Personnel',subcategory:'Accidents',name:`Dossier accident · ${accident.jobName}`,type:'Accident de travail',owner:person.name,status:accident.complete?'Complet':'À compléter',date:accident.date,link:'person',linkId:person.id}));
 });
 jobs.forEach(job=>(job.documents||[]).forEach(document=>{const type=(document.type||'').toLowerCase(),subcategory=type.includes('sécurité')?'Sécurité chantier':type.includes('autorisation')?'Autorisations':'Plans & métrés';list.push({id:`job-${job.id}-${document.id}`,category:'Chantiers',subcategory,name:document.name,type:document.type,owner:job.name,status:document.status,date:document.date,link:'job',linkId:job.id})}));
 return list;
};
filteredDocuments=function(){const query=docQuery.trim().toLocaleLowerCase('fr');return documentsInCurrentView().filter(record=>(docCategory==='Tous'||record.category===docCategory)&&(docSubcategory==='Tous'||record.subcategory===docSubcategory)&&(!query||[record.name,record.type,record.owner,record.subcategory].join(' ').toLocaleLowerCase('fr').includes(query))).sort((a,b)=>(b.date||'').localeCompare(a.date||''))};
function subcategoryCards(){const node=documentTree[docCategory],records=documentsInCurrentView().filter(d=>d.category===docCategory);return `<div class="document-subfolders"><button class="${docSubcategory==='Tous'?'selected':''}" onclick="docSubcategory='Tous';render()"><span class="folder-icon">${icon('folder')}</span><span><strong>Tout ${docCategory.toLowerCase()}</strong><small>Toutes les sous-catégories</small></span><b>${records.length}</b></button>${node.children.map(child=>{const count=records.filter(d=>d.subcategory===child).length;return `<button class="${docSubcategory===child?'selected':''}" onclick="docSubcategory='${child}';render()"><span class="folder-icon">${icon('folder')}</span><span><strong>${esc(child)}</strong><small>Ouvrir ce classement</small></span><b>${count}</b></button>`}).join('')}</div>`}
documents=function(){if(docCategory==='Tous')return `<div class="simple-head"><div><p class="eyebrow">CLASSEMENT</p><h1>Documents</h1><p>Commencez par une catégorie, puis ouvrez uniquement la sous-catégorie utile.</p></div></div><div class="document-folders airy-folders">${Object.entries(documentTree).map(([category,node])=>{const count=documentsInCurrentView().filter(d=>d.category===category).length;return `<button onclick="docCategory='${category}';docSubcategory='Tous';docQuery='';render()"><span class="folder-icon">${icon('folder')}</span><span><strong>${esc(category)}</strong><small>${esc(node.description)}</small></span><b>${count}</b></button>`}).join('')}</div><p class="help-line">Les documents restent reliés à leur dossier d’origine. Les références affichées sont des exemples à remplacer par les pièces réelles.</p>`;const node=documentTree[docCategory];if(!node){docCategory='Tous';docSubcategory='Tous';return documents()}return `<div class="simple-head"><div><button class="link" onclick="docCategory='Tous';docSubcategory='Tous';docQuery='';render()">← Toutes les catégories</button><h1>${esc(docCategory)}</h1><p>${esc(node.description)}</p></div></div>${subcategoryCards()}<div class="document-toolbar"><input aria-label="Rechercher dans ${esc(docCategory)}" placeholder="Rechercher un document, une personne…" value="${esc(docQuery)}" oninput="docQuery=this.value;refreshDocumentRows()"></div><section class="panel" id="documentRows">${documentRows()}</section>`};

// Profitability is readable both job by job and team by team.
function profitabilityTeams(job){const linkedIds=[...new Set([...assignments.filter(item=>String(item.job)===String(job.id)).map(item=>item.team),...(job.timeEntries||[]).map(item=>item.team)].filter(id=>id!=null&&id!=='').map(String))];if(linkedIds.length)return linkedIds.map(id=>teams.find(team=>String(team.id)===id)).filter(Boolean);const spec=demoJobSpecs.find(item=>item.id===job.id+100);return spec?.team==null?[]:teams.filter(team=>String(team.id)===String(spec.team))}
function profitabilityTone(rate){return rate<0?'profit-loss':rate<12?'profit-watch':'profit-gain'}
profitabilityView=function(){const rows=jobs.filter(job=>acceptedQuoteForJob(job.id)&&job.phase!=='À préparer').map(job=>({job,finance:projectedJobFinance(job),teams:profitabilityTeams(job)})).sort((a,b)=>a.finance.forecastRate-b.finance.forecastRate),net=rows.reduce((sum,row)=>sum+row.finance.net,0),margin=rows.reduce((sum,row)=>sum+row.finance.forecastMargin,0),teamRows=teams.map(team=>{const selected=rows.filter(row=>row.teams.length===1&&row.teams[0].id===team.id);return {team,jobs:selected.length,revenue:selected.reduce((sum,row)=>sum+row.finance.net,0),cost:selected.reduce((sum,row)=>sum+row.finance.forecast,0),margin:selected.reduce((sum,row)=>sum+row.finance.forecastMargin,0),actual:selected.reduce((sum,row)=>sum+row.finance.hours,0),planned:selected.reduce((sum,row)=>sum+row.finance.plannedHours,0),surface:selected.reduce((sum,row)=>sum+Number(row.job.surface||0),0)}}).filter(row=>row.jobs);return managementTabs('profitability')+heading('Rentabilité des chantiers','Les résultats sont visibles par chantier, puis regroupés par équipe.',false)+`<div class="profit-kpis"><div><small>Chantiers analysés</small><strong>${rows.length}</strong></div><div><small>Chiffre d’affaires HT</small><strong>${money(net)}</strong></div><div class="${margin<0?'profit-loss':'profit-gain'}"><small>Marge projetée</small><strong>${money(margin)}</strong><span>${net?(margin/net*100).toFixed(1):'0'} %</span></div></div><section class="panel profit-table realistic-profit"><div class="panel-head"><div><p class="eyebrow">CHANTIER PAR CHANTIER</p><h2>Résultat projeté</h2></div><div class="profit-key"><span class="gain-dot"></span>Bénéfice <span class="loss-dot"></span>Perte</div></div><div class="profit-head"><span>Chantier / ouvrage</span><span>Surface</span><span>Équipe</span><span>Heures réelles / prévues</span><span>Vendu HT</span><span>Coût projeté</span><span>Marge projetée</span></div>${rows.map(({job,finance,teams})=>`<button class="${profitabilityTone(finance.forecastRate)}" onclick="showJob(${job.id})"><span><strong>${esc(job.name)}</strong><small>${esc(job.workType)} · ${esc(job.phase)}</small></span><span>${job.surface?job.surface+' m²':'ouvrage linéaire'}</span><span>${teams.length===1?esc(teams[0].name):teams.length?'Plusieurs équipes · résultat non ventilé':'Équipe non définie'}</span><span><b>${finance.hours.toFixed(0)} / ${finance.plannedHours.toFixed(0)} h</b><small>${finance.plannedHours?Math.round(finance.hours/finance.plannedHours*100):0} % consommé</small></span><span>${money(finance.net)}</span><span>${money(finance.forecast)}</span><b>${money(finance.forecastMargin)}<small>${finance.forecastRate.toFixed(1)} %</small></b></button>`).join('')}</section><section class="panel team-profitability"><div class="panel-head"><div><p class="eyebrow">TOTAL PAR ÉQUIPE</p><h2>Comparaison des équipes</h2><span>Seuls les chantiers attribués à une équipe unique sont totalisés. Les chantiers multiéquipes restent dans le résultat global sans ventilation.</span></div></div><div class="data-table"><table><thead><tr><th>Équipe</th><th>Chantiers</th><th>Surface</th><th>Heures réelles</th><th>Heures prévues</th><th>Chiffre d’affaires HT</th><th>Coûts projetés</th><th>Résultat</th></tr></thead><tbody>${teamRows.map(row=>{const rate=row.revenue?row.margin/row.revenue*100:0;return `<tr class="${profitabilityTone(rate)}"><td><strong>${esc(row.team.name)}</strong><small>${row.team.members.length} personnes</small></td><td>${row.jobs}</td><td>${row.surface} m²</td><td>${row.actual.toFixed(0)} h</td><td>${row.planned.toFixed(0)} h</td><td>${money(row.revenue)}</td><td>${money(row.cost)}</td><td><strong>${money(row.margin)}</strong><small>${rate.toFixed(1)} %</small></td></tr>`}).join('')}</tbody></table></div></section><p class="notice"><strong>Données de démonstration, pas une norme de rendement.</strong> Les heures sont des heures-personnes et le coût horaire interne est fictif. Les chiffres réels devront venir des heures, achats, sous-traitants, déchets et imprévus enregistrés.</p>`}

// Every time correction stays attached to the original entry and can be reviewed.
const showJobBeforeCorrectionHistory=showJob;
showJob=function(id){showJobBeforeCorrectionHistory(id);const job=jobs.find(item=>item.id===id),corrections=(job?.timeEntries||[]).flatMap(entry=>(entry.corrections||[]).map(correction=>({entry,correction,team:teams.find(team=>team.id===entry.team)})));if(!corrections.length)return;const node=document.querySelector('#modalbody'),section=`<section class="correction-history"><div class="section-heading"><h3>Corrections de pointage</h3><span class="badge">${corrections.length}</span></div>${corrections.map(({entry,correction,team})=>`<article><div><strong>${fullDate(entry.date)} · ${esc(team?.name||'Équipe')}</strong><small>Original ${esc(correction.original.arrival)} → ${esc(correction.original.departure||'—')} · proposé ${esc(correction.proposed.arrival)} → ${esc(correction.proposed.departure||'—')}</small><p>${esc(correction.reason)} · demandé par ${esc(correction.requestedBy)}</p></div><span class="badge ${correction.status==='Acceptée'?'green':correction.status==='Refusée'?'red':'warn'}">${esc(correction.status)}</span>${correction.status==='À valider'?`<div><button class="btn" onclick="approveTimeCorrection(${job.id},'${jsString(entry.id)}','${jsString(correction.id)}',false)">Refuser</button><button class="btn primary" onclick="approveTimeCorrection(${job.id},'${jsString(entry.id)}','${jsString(correction.id)}',true)">Accepter</button></div>`:''}</article>`).join('')}</section>`;node.innerHTML=node.innerHTML.replace(/<\/div>\s*$/,section+'</div>')}

// Asset lists never become a closed vocabulary: the company can provide its own values.
assetForm=function(id){const asset=assets.find(item=>item.id===id)||{name:'',category:'Machine',mode:'Achat',provider:'',reference:'',start:reference,end:'',monthly:0,responsible:'',attached:'',contents:'',condition:'En service'};modal(id?'Modifier le bien':'Ajouter un bien',`<form onsubmit="saveCustomAsset(event,${id||0})"><label>Nom du bien ou du lot<input name="name" required maxlength="100" value="${esc(asset.name)}"></label><div class="form-two"><label>Catégorie proposée<select name="category">${['Camionnette équipée','Camion équipé','Remorque','Échafaudage','Lot de machines','Machine','Outillage','Autre bien'].map(value=>`<option ${value===asset.category?'selected':''}>${value}</option>`).join('')}</select></label><label>Financement proposé<select name="mode">${['Achat','Leasing','Location','Mise à disposition'].map(value=>`<option ${value===asset.mode?'selected':''}>${value}</option>`).join('')}</select></label><label>Fournisseur / financeur<input name="provider" required maxlength="100" value="${esc(asset.provider)}"></label><label>Référence du contrat / facture<input name="reference" required maxlength="80" value="${esc(asset.reference)}"></label><label>Date de début / achat<input type="date" name="start" required value="${asset.start}"></label><label>Fin du financement / location<input type="date" name="end" value="${asset.end||''}"></label><label>Mensualité HT (€)<input type="number" name="monthly" min="0" step="0.01" value="${asset.monthly||0}" required></label><label>État proposé<select name="condition">${['En service','À contrôler','À réparer','En réparation','Hors service'].map(value=>`<option ${value===asset.condition?'selected':''}>${value}</option>`).join('')}</select></label><label>Responsable<input name="responsible" required maxlength="80" value="${esc(asset.responsible)}"></label></div><label>Rattaché à (véhicule, équipe, dépôt…)<input name="attached" required maxlength="100" value="${esc(asset.attached)}"></label><label>Contenu / équipement permanent<input name="contents" maxlength="600" value="${esc(asset.contents)}"></label><details class="custom-values"><summary>La valeur voulue n’est pas dans la liste ?</summary><p>Écrivez uniquement les valeurs à remplacer. Les champs laissés vides conserveront le choix fait au-dessus.</p><div class="form-two"><label>Ma catégorie<input name="customCategory" maxlength="80" placeholder="Ex. grue sur remorque" value="${asset.customCategory?esc(asset.category):''}"></label><label>Mon financement<input name="customMode" maxlength="80" placeholder="Ex. crédit-bail spécifique" value="${asset.customMode?esc(asset.mode):''}"></label><label>Mon état<input name="customCondition" maxlength="80" placeholder="Ex. en attente de pièce" value="${asset.customCondition?esc(asset.condition):''}"></label><label>Mon type / sous-catégorie<input name="customType" maxlength="80" placeholder="Ex. levage" value="${esc(asset.customType||'')}"></label></div></details><p id="assetError" class="form-error" role="alert"></p><p class="help-line">Chaque modification de rattachement ou de valeur personnalisée reste dans l’historique.</p><div class="modal-actions"><button class="btn primary">Enregistrer le dossier</button></div></form>`)}
function saveCustomAsset(event,id){event.preventDefault();const form=new FormData(event.target),existing=assets.find(item=>item.id===id),before=new Set(assets.map(item=>item.id)),category=form.get('customCategory').trim()||form.get('category').trim(),mode=form.get('customMode').trim()||form.get('mode').trim(),condition=form.get('customCondition').trim()||form.get('condition').trim(),data={name:form.get('name').trim(),category,mode,condition,provider:form.get('provider').trim(),reference:form.get('reference').trim(),start:form.get('start'),end:form.get('end'),monthly:+form.get('monthly')||0,responsible:form.get('responsible').trim(),attached:form.get('attached').trim(),contents:form.get('contents').trim(),customType:form.get('customType').trim(),customCategory:Boolean(form.get('customCategory').trim()),customMode:Boolean(form.get('customMode').trim()),customCondition:Boolean(form.get('customCondition').trim())};if(!data.name||!data.provider||!data.reference||!data.responsible||!data.attached){document.querySelector('#assetError').textContent='Complétez les champs obligatoires.';return}if(form.get('mode')==='Leasing'&&!form.get('customMode')&&(!data.end||data.end<data.start)){document.querySelector('#assetError').textContent='Renseignez une fin de leasing postérieure ou égale au début.';return}let asset=existing;if(asset){asset.history??=[];const changes=[];if(asset.attached!==data.attached)changes.push(`rattachement : ${asset.attached} → ${data.attached}`);if(asset.category!==data.category)changes.push(`catégorie : ${asset.category} → ${data.category}`);if(asset.mode!==data.mode)changes.push(`financement : ${asset.mode} → ${data.mode}`);if(changes.length)asset.history.push({date:reference,text:'Modification · '+changes.join(' · ')});Object.assign(asset,data)}else{asset={id:Date.now(),group:'tools',...data,history:[{date:reference,text:'Dossier créé avec les catégories choisies par l’entreprise.'}],docs:[]};while(before.has(asset.id))asset.id++;assets.push(asset)}closeModal();render();showAsset(asset.id);toast('Dossier du bien mis à jour.')}

// Personnel can leave the active roster without destroying historical hours and job profitability.
function activePeople(){return people.filter(person=>!person.inactiveAt)}
function withActivePeople(renderer){const all=people;people=activePeople();try{return renderer()}finally{people=all}}
const peopleBeforeDepartures=peopleView;
peopleView=function(){const active=withActivePeople(()=>peopleBeforeDepartures()),former=people.filter(person=>person.inactiveAt);return active+(former.length?`<section class="panel former-people"><div class="panel-head"><div><p class="eyebrow">HISTORIQUE DU PERSONNEL</p><h2>Anciens collaborateurs <span class="count">${former.length}</span></h2><span>Les heures et chantiers passés restent conservés.</span></div></div><div class="data-table"><table><thead><tr><th>Personne</th><th>Ancienne fonction</th><th>Date de sortie</th><th>Motif</th><th></th></tr></thead><tbody>${former.map(person=>`<tr><td><strong>${esc(person.name)}</strong></td><td>${esc(person.role)}</td><td>${fullDate(person.inactiveAt)}</td><td>${esc(person.inactiveReason||'Non précisé')}</td><td><button class="link" onclick="restorePerson(${person.id})">Réintégrer</button></td></tr>`).join('')}</tbody></table></div></section>`:'')}
const personalBeforeInactiveFilter=personalView;
personalView=function(){return withActivePeople(()=>{if(!getPerson(personalPreviewId))personalPreviewId=people[0]?.id||0;return personalBeforeInactiveFilter()})}
const reminderBeforeInactiveFilter=reminderForm;
reminderForm=function(id='',type='company',linkId=0){return withActivePeople(()=>reminderBeforeInactiveFilter(id,type,linkId))}
const paySlipFormBeforeInactiveFilter=paySlipForm;
paySlipForm=function(personId=0){return withActivePeople(()=>paySlipFormBeforeInactiveFilter(personId))}
const showPersonBeforeDeparture=showPersonDossier;
showPersonDossier=function(id){showPersonBeforeDeparture(id);const person=getPerson(id),node=document.querySelector('#modalbody');if(!person||!node)return;const actions=person.inactiveAt?`<section class="departure-actions"><p>Cette personne ne fait plus partie de l’effectif actif. Son historique est conservé.</p><button class="btn" onclick="restorePerson(${id})">Réintégrer dans l’entreprise</button></section>`:id===1?'':`<section class="departure-actions"><p>Départ, fin de contrat ou erreur d’encodage.</p><button class="btn danger" onclick="retirePersonForm(${id})">Retirer de l’entreprise</button></section>`;node.innerHTML=node.innerHTML.replace(/<\/div>\s*$/,actions+'</div>')}
function retirePersonForm(id){const person=getPerson(id);if(!person||id===1)return;modal('Retirer '+person.name,`<form onsubmit="retirePerson(event,${id})"><label>Date de sortie<input name="date" type="date" required value="${reference}"></label><label>Motif<textarea name="reason" rows="3" required maxlength="300" placeholder="Fin de contrat, départ volontaire, doublon…"></textarea></label><p class="notice"><strong>L’historique ne sera pas effacé.</strong> La personne disparaîtra des équipes, des prochaines affectations et des destinataires d’alertes, mais ses heures passées resteront dans les chantiers.</p><div class="modal-actions"><button type="button" class="btn" onclick="showPersonDossier(${id})">Annuler</button><button class="btn danger">Confirmer la sortie</button></div></form>`)}
