// The owner can add auditable amounts that immediately affect job and team profitability.
const projectedJobFinanceBeforeAdjustments=projectedJobFinance;
projectedJobFinance=function(job){const base=projectedJobFinanceBeforeAdjustments(job),active=(job.finance?.adjustments||[]).filter(item=>!item.voidedAt),manualRevenue=active.reduce((sum,item)=>sum+(item.type==='revenue'?item.amount:item.type==='credit'?-item.amount:0),0),manualCost=active.reduce((sum,item)=>sum+(item.type==='cost'?item.amount:item.type==='saving'?-item.amount:0),0),net=base.net+manualRevenue,forecast=base.forecast+manualCost;return {...base,net,forecast,forecastMargin:net-forecast,forecastRate:net?(net-forecast)/net*100:0,manualRevenue,manualCost}};
function profitabilityAdjustmentLabel(type){return {revenue:'Recette supplémentaire',cost:'Coût supplémentaire',credit:'Avoir / remise client',saving:'Réduction de coût'}[type]||type}
function allProfitabilityAdjustments(){return jobs.flatMap(job=>(job.finance?.adjustments||[]).map(item=>({job,item}))).sort((a,b)=>(b.item.date||'').localeCompare(a.item.date||''))}
function profitabilityAdjustmentsView(){const rows=allProfitabilityAdjustments();return `<section class="panel profitability-adjustments"><div class="panel-head"><div><p class="eyebrow">AJUSTEMENTS DU PATRON</p><h2>Montants ajoutés aux chantiers</h2><span>Suppléments, imprévus, avoirs et économies avec leur historique.</span></div><button class="btn primary" onclick="profitabilityAdjustmentForm()">+ Ajouter un montant</button></div>${rows.length?`<div class="data-table"><table><thead><tr><th>Date</th><th>Chantier</th><th>Nature</th><th>Motif</th><th>Montant</th><th>Trace</th><th></th></tr></thead><tbody>${rows.map(({job,item})=>`<tr class="${item.voidedAt?'voided-adjustment':''}"><td>${fullDate(item.date)}</td><td><strong>${esc(job.name)}</strong></td><td>${esc(profitabilityAdjustmentLabel(item.type))}</td><td>${esc(item.label)}<small>${esc(item.note||'')}</small></td><td class="${item.type==='revenue'||item.type==='saving'?'adjustment-positive':'adjustment-negative'}"><strong>${item.type==='revenue'||item.type==='saving'?'+':'−'} ${money(item.amount)}</strong></td><td>${item.voidedAt?`<span class="badge red">Annulé</span>`:`<small>${esc(item.createdBy)}<br>${fullDate(item.createdAt?.slice(0,10)||item.date)}</small>`}</td><td>${item.voidedAt?'':`<button class="link" onclick="profitabilityAdjustmentForm(${job.id},'${jsString(item.id)}')">Modifier</button><button class="link danger-text" onclick="voidProfitabilityAdjustment(${job.id},'${jsString(item.id)}')">Annuler</button>`}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Aucun montant manuel ajouté. Les calculs utilisent uniquement les devis, heures et coûts enregistrés.</div>'}</section>`}
function profitabilityAdjustmentForm(jobId=0,id=''){if(!requireField('viewProfitability','La rentabilité est réservée au patron.'))return;const job=jobs.find(item=>item.id===jobId),adjustment=job?.finance?.adjustments?.find(item=>item.id===id)||{date:reference,type:'cost',label:'',amount:'',note:''};modal(id?'Modifier le montant':'Ajouter un montant à la rentabilité',`<form onsubmit="saveProfitabilityAdjustment(event,${jobId},'${jsString(id)}')"><div class="form-two"><label>Chantier<select name="job" required ${id?'disabled':''}><option value="">Choisir le chantier…</option>${jobs.filter(item=>acceptedQuoteForJob(item.id)).map(item=>`<option value="${item.id}" ${item.id===jobId?'selected':''}>${esc(item.name)}</option>`).join('')}</select>${id?`<input type="hidden" name="job" value="${jobId}">`:''}</label><label>Date<input name="date" type="date" required value="${adjustment.date}"></label><label>Nature<select name="type"><option value="revenue" ${adjustment.type==='revenue'?'selected':''}>Recette supplémentaire</option><option value="cost" ${adjustment.type==='cost'?'selected':''}>Coût supplémentaire</option><option value="credit" ${adjustment.type==='credit'?'selected':''}>Avoir / remise client</option><option value="saving" ${adjustment.type==='saving'?'selected':''}>Réduction de coût</option></select></label><label>Montant HT (€)<input name="amount" type="number" min="0.01" step="0.01" required value="${adjustment.amount}"></label></div><label>Motif<input name="label" required maxlength="160" value="${esc(adjustment.label)}" placeholder="Ex. supplément de zinguerie demandé par le client"></label><label>Note / référence<textarea name="note" rows="3" maxlength="500" placeholder="Bon de commande, facture fournisseur, explication…">${esc(adjustment.note||'')}</textarea></label><p class="notice">Le montant modifiera immédiatement le résultat du chantier et le total de son équipe. Chaque changement reste daté.</p><div class="modal-actions"><button class="btn primary">Enregistrer et recalculer</button></div></form>`)}
function saveProfitabilityAdjustment(event,jobId,id){event.preventDefault();if(!requireField('viewProfitability','La rentabilité est réservée au patron.'))return;const form=new FormData(event.target),job=jobs.find(item=>item.id===(jobId||+form.get('job'))),amount=+form.get('amount');if(!job||!Number.isFinite(amount)||amount<=0)return;job.finance??={};job.finance.adjustments??=[];const existing=job.finance.adjustments.find(item=>item.id===id),data={date:form.get('date'),type:form.get('type'),label:form.get('label').trim(),amount,note:form.get('note').trim(),updatedAt:new Date().toISOString(),updatedBy:'Patron'};if(existing){existing.history??=[];existing.history.push({at:new Date().toISOString(),by:'Patron',previous:{date:existing.date,type:existing.type,label:existing.label,amount:existing.amount,note:existing.note}});Object.assign(existing,data)}else job.finance.adjustments.push({id:'adjustment-'+crypto.randomUUID(),...data,createdAt:new Date().toISOString(),createdBy:'Patron',history:[]});closeModal();render();toast('Montant ajouté et rentabilité recalculée.')}
function voidProfitabilityAdjustment(jobId,id){if(!requireField('viewProfitability','La rentabilité est réservée au patron.'))return;const item=jobs.find(job=>job.id===jobId)?.finance?.adjustments?.find(item=>item.id===id);if(!item)return;item.voidedAt=new Date().toISOString();item.voidedBy='Patron';render();toast('Montant annulé. La trace reste conservée.')}
