function createJobFromQuote(form,client,title){const id=Date.now(),name=form.get('newJobName').trim();if(!name)return null;const job={id,name,client,town:form.get('newJobTown').trim(),address:form.get('newJobAddress').trim()||form.get('clientAddress').trim(),phase:'À préparer',type:title,workType:title,progress:0,color:'blue',required:[],photos:[],surface:+form.get('newJobSurface')||0,execution:[],materials:[],contacts:[],notes:[],documents:[],dailyChecks:{},timeEntries:[],finance:{hourlyCost:48,plannedHours:0,materials:0,materialsBudget:0,subcontracting:0,subcontractingBudget:0,other:0,otherBudget:0,adjustments:[]}};jobs.push(job);return job}
function saveLinkedQuote(event,id){event.preventDefault();if(!canModuleAction('quotes',id?'edit':'add'))return denyAccess('Vous ne pouvez pas enregistrer ce devis.');const form=new FormData(event.target),labels=form.getAll('label'),descriptions=form.getAll('description'),qtys=form.getAll('qty'),units=form.getAll('unit'),prices=form.getAll('price'),vats=form.getAll('vat');if(!labels.length||labels.some(value=>!value.trim())){document.querySelector('#quoteError').textContent='Ajoutez au moins une ligne de travaux.';return}const title=form.get('title').trim(),client=form.get('client').trim(),newName=form.get('newJobName').trim();let job=jobs.find(item=>item.id===+form.get('job'));if(newName&&!id)job=createJobFromQuote(form,client,title);if(!job){document.querySelector('#quoteError').textContent='Choisissez un chantier existant ou écrivez le nom du nouveau chantier.';return}const lines=labels.map((label,index)=>({label:label.trim(),description:(descriptions[index]||'').trim(),qty:+qtys[index],unit:(units[index]||'forfait').trim(),price:+prices[index],vat:+vats[index]})),data={title,job:job.id,client,clientAddress:form.get('clientAddress').trim(),date:form.get('date'),validUntil:form.get('validUntil'),deposit:+form.get('deposit')||0,paymentTerms:form.get('paymentTerms').trim(),notes:form.get('notes').trim(),exclusions:form.get('exclusions').trim(),lines};let quote=quotes.find(item=>item.id===id);if(quote)Object.assign(quote,data);else quotes.push({id:Date.now()+1,ref:'DEV-'+new Date().getFullYear()+'-'+String(14+quotes.length).padStart(3,'0'),status:'Brouillon',...data});job.client=client;job.type||=title;job.workType||=title;job.execution=lines.map(line=>line.label);closeModal();navigate('quotes');toast(newName?'Devis enregistré et nouveau chantier créé partout.':'Devis enregistré et relié au chantier.')}

