function expenseReceiptForm(){if(!requireField('submitExpense','Vous ne pouvez pas déposer de dépense.'))return;modal('Déposer un ticket ou une facture',`<form onsubmit="saveExpenseReceipt(event)"><div class="form-two"><label>Date<input name="date" type="date" required value="${reference}"></label><label>Catégorie<select name="category"><option>Matériaux</option><option>Restaurant / repas</option><option>Outillage</option><option>Carburant</option><option>Parking / déplacement</option><option>Autre dépense</option></select></label><label>Montant TVAC (€)<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Chantier lié<select name="job"><option value="0">Aucun / frais généraux</option>${activeJobsForPlanning().map(job=>`<option value="${job.id}">${esc(job.name)}</option>`).join('')}</select></label></div><label>Commerce / fournisseur<input name="supplier" required maxlength="120"></label><label>Photo du ticket ou de la facture<input name="file" type="file" accept="image/*,application/pdf" capture="environment" required></label><label>Remarque<input name="note" maxlength="400"></label><p class="notice">La comptabilité retrouvera la pièce, son auteur, son chantier et son montant dans un seul registre.</p><div class="modal-actions"><button class="btn primary">Envoyer à la comptabilité</button></div></form>`)}
