const accountingBeforeExpenseReceipts=accountingView;accountingView=function(){const pipeline=`<section class="panel quote-accounting-pipeline"><div class="panel-head"><div><p class="eyebrow">DEVIS LIÉS</p><h2>Devis à suivre en comptabilité</h2><span>Tout nouveau devis apparaît automatiquement ici avec son chantier.</span></div></div><div class="data-table"><table><thead><tr><th>Devis</th><th>Chantier</th><th>Client</th><th>Montant TVAC</th><th>État</th></tr></thead><tbody>${quotes.slice(-12).reverse().map(quote=>`<tr><td><strong>${esc(quote.ref)}</strong></td><td>${esc(jobs.find(job=>job.id===quote.job)?.name||'—')}</td><td>${esc(quote.client)}</td><td>${money(quoteGross(quote))}</td><td><span class="badge ${quote.status==='Accepté'?'green':'warn'}">${esc(quote.status)}</span></td></tr>`).join('')}</tbody></table></div></section>`;return accountingBeforeExpenseReceipts()+pipeline+expenseReceiptsView()};
const compactTerrainBeforeExpenses=compactTerrainHome;compactTerrainHome=function(){return compactTerrainBeforeExpenses().replace('Signaler un problème</button>','Signaler un problème</button><button class="btn" onclick="expenseReceiptForm()">📷 Déposer un ticket</button>')};

// Catalogue shared by the office and field teams: a scheduled session also appears in the shared calendar.
let trainingCatalogue=[{id:'training-asbestos',title:'Désamiantage',provider:'Constructiv',location:'Belgique · centres selon session',contact:'Catalogue Constructiv',phone:'',email:'',website:'https://constructiv.be/fr/formation/differentes-formations/formations-obligatoires/',duration:'8 h (travaux simples) ou 32 h (zone fermée)',date:'',note:'Formation obligatoire selon le type d’exposition ; recyclage annuel requis.'},{id:'training-safety',title:'Formation de base à la sécurité',provider:'Constructiv',location:'Centres Constructiv · Wallonie et Bruxelles',contact:'Catalogue des formations',phone:'',email:'',website:'https://education.constructiv.be/fr/training-search',duration:'8 h',date:'',note:'Base sécurité pour les métiers de la construction.'},{id:'training-height',title:'Travail en hauteur et échafaudages',provider:'Constructiv',location:'Centres selon session',contact:'Catalogue Constructiv',phone:'',email:'',website:'https://constructiv.be/fr/formation/differentes-formations/formations-obligatoires/',duration:'Selon module',date:'',note:'Utilisation, montage, démontage ou transformation d’échafaudages.'}];
let trainingInterest=[];
function trainingCatalogueView(){const rows=[...trainingCatalogue].sort((a,b)=>a.title.localeCompare(b.title,'fr')),interests=trainingInterest.filter(item=>item.status==='Nouveau').length;return heading('Formations','Les possibilités réelles du métier, centralisées pour que chacun puisse les découvrir.',false)+`<section class="panel training-catalogue"><div class="panel-head"><div><p class="eyebrow">CATALOGUE PARTAGÉ</p><h2>Formations possibles <span class="count">${rows.length}</span></h2><span>Accessible au patron comme aux ouvriers.</span></div>${sessionAccessKey==='owner'?`<button class="btn primary" onclick="trainingCatalogueForm()">+ Ajouter</button>`:''}</div>${rows.map(item=>`<article class="training-card"><div><span class="badge">${esc(item.duration||'Durée à confirmer')}</span><h3>${esc(item.title)}</h3><p>${esc(item.note||'')}</p><div class="detail-row"><span>Organisme</span><b>${esc(item.provider||'À renseigner')}</b></div><div class="detail-row"><span>Lieu</span><b>${esc(item.location||'À renseigner')}</b></div>${item.website?`<a class="link" href="${esc(item.website)}" target="_blank" rel="noopener noreferrer">Source et modalités ↗</a>`:''}</div><button class="btn primary" onclick="showTrainingInterest('${jsString(item.id)}')">Ça m’intéresse</button></article>`).join('')}</section>${sessionAccessKey==='owner'?`<section class="panel"><div class="panel-head"><div><p class="eyebrow">INTÉRÊTS DE L’ÉQUIPE</p><h2>Demandes reçues <span class="count">${interests}</span></h2></div></div>${trainingInterest.length?`<div class="data-table"><table><thead><tr><th>Formation</th><th>Personne</th><th>Message</th><th>Date</th></tr></thead><tbody>${trainingInterest.map(item=>`<tr><td>${esc(trainingCatalogue.find(training=>training.id===item.trainingId)?.title||'Formation')}</td><td>${esc(item.person)}</td><td>${esc(item.note||'')}</td><td>${fullDate(item.date)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Aucun intérêt transmis pour le moment.</div>'}</section>`:''}`}
function showTrainingInterest(id){const training=trainingCatalogue.find(item=>item.id===id);if(!training)return;modal('Intérêt pour une formation',`<form onsubmit="saveTrainingInterest(event,'${jsString(id)}')"><p><strong>${esc(training.title)}</strong><br>${esc(training.provider)} · ${esc(training.location)}</p><label>Pourquoi cette formation vous intéresse ?<textarea name="note" rows="4" maxlength="500" placeholder="Ex. utile pour évoluer, chantier à venir, envie d’apprendre…"></textarea></label><p class="notice">Votre intérêt sera transmis au patron. Cela ne constitue pas une inscription.</p><div class="modal-actions"><button class="btn primary">Transmettre mon intérêt</button></div></form>`)}
function saveTrainingInterest(event,id){event.preventDefault();const person=sessionPerson(),training=trainingCatalogue.find(item=>item.id===id);if(!training)return;trainingInterest.push({id:'training-interest-'+crypto.randomUUID(),trainingId:id,person:person?.name||'Patron',note:String(new FormData(event.target).get('note')||'').trim(),date:reference,status:'Nouveau'});closeModal();toast('Votre intérêt a été transmis au patron.')}
function trainingCatalogueForm(id=''){const item=trainingCatalogue.find(entry=>entry.id===id)||{title:'',provider:'',location:'',website:'',duration:'',note:''};modal(id?'Modifier la formation':'Ajouter une formation',`<form onsubmit="saveTrainingCatalogue(event,'${jsString(id)}')"><div class="form-two"><label>Intitulé<input name="title" required maxlength="150" value="${esc(item.title)}"></label><label>Durée / prérequis<input name="duration" maxlength="120" value="${esc(item.duration)}"></label><label>Organisme<input name="provider" maxlength="150" value="${esc(item.provider)}"></label><label>Lieu<input name="location" maxlength="150" value="${esc(item.location)}"></label><label>Source officielle<input name="website" type="url" maxlength="300" value="${esc(item.website)}"></label></div><label>Ce que la formation apporte<textarea name="note" rows="3" maxlength="600">${esc(item.note)}</textarea></label><div class="modal-actions"><button class="btn primary">Enregistrer</button></div></form>`) }
function saveTrainingCatalogue(event,id){event.preventDefault();const form=new FormData(event.target),data=Object.fromEntries(['title','provider','location','website','duration','note'].map(key=>[key,String(form.get(key)||'').trim()]));if(!data.title)return;const current=trainingCatalogue.find(entry=>entry.id===id);if(current)Object.assign(current,data);else trainingCatalogue.push({id:'training-catalogue-'+crypto.randomUUID(),...data});closeModal();render();toast('Formation enregistrée dans le catalogue partagé.')}
const snapshotBeforeTrainingCatalogue=workspaceSnapshot;workspaceSnapshot=function(){const state=JSON.parse(snapshotBeforeTrainingCatalogue());state.trainingCatalogue=trainingCatalogue;state.trainingInterest=trainingInterest;return JSON.stringify(state)};
const restoreBeforeTrainingCatalogue=restoreWorkspace;restoreWorkspace=function(state){restoreBeforeTrainingCatalogue(state);if(Array.isArray(state.trainingCatalogue))trainingCatalogue=state.trainingCatalogue;if(Array.isArray(state.trainingInterest))trainingInterest=state.trainingInterest};
if(!tabs2.some(([key])=>key==='training'))tabs2.splice(tabs2.findIndex(([key])=>key==='jobs'),0,['training','Formations']);

function quickContextPhotoForm(jobId){const job=jobs.find(item=>item.id===jobId);if(!job)return;modal('Ajouter une photo',`<form onsubmit="saveQuickContextPhoto(event,${jobId})"><label class="upload-field">📷 Photo<input name="photo" type="file" accept="image/*" capture="environment" required></label><label>Note facultative<input name="note" maxlength="250" placeholder="Ajouter une précision…"></label><div class="modal-actions"><button class="btn primary">Ajouter</button></div></form>`)}
function saveQuickContextPhoto(event,jobId){event.preventDefault();const form=new FormData(event.target),file=form.get('photo'),job=jobs.find(item=>item.id===jobId);if(!job||!file?.size)return;job.notes??=[];job.notes.push({id:Date.now(),date:reference,author:'Utilisateur connecté',visibility:'Équipe et patron',text:String(form.get('note')||'').trim(),photoName:file.name,photoUrl:URL.createObjectURL(file)});closeModal();showJob(jobId);toast('Photo ajoutée au chantier.')}
const showJobBeforeContextCamera=showJob;
showJob=function(id){showJobBeforeContextCamera(id);const actions=document.querySelector('#modalbody .job-actions');if(actions&&!actions.querySelector('.context-camera'))actions.insertAdjacentHTML('beforeend',`<button class="btn context-camera" title="Prendre une photo" onclick="quickContextPhotoForm(${id})">📷 Photo</button>`)};

// Keep the home concise: formations are discovered from the news area, not through another permanent tab.
const trainingTabIndex=tabs2.findIndex(([key])=>key==='training');if(trainingTabIndex>=0)tabs2.splice(trainingTabIndex,1);
const homeNewsBeforeTrainingShortcut=homeNews;
homeNews=function(){return homeNewsBeforeTrainingShortcut().replace('</div><p class="help-line">','</div><button class="btn" onclick="navigate(\'training\')">Formations possibles →</button><p class="help-line">')};
const fieldTimeFormBeforeHint=fieldTimeForm;
fieldTimeForm=function(){fieldTimeFormBeforeHint();const note=document.querySelector('#modalbody [name="note"]');if(note)note.insertAdjacentHTML('afterend','<p class="help-line">Pensez à noter : absence, travaux réalisés, imprévu ou matériel manquant.</p>')};

let quoteDrafts=[];
function legacyQuoteDraftForm(){modal('Ébauche de devis',`<form onsubmit="saveQuoteDraft(event)"><p class="notice">Sur place : notez l’essentiel. Vous terminerez le vrai devis plus tard.</p><div class="form-two"><label>Client ou adresse<input name="place" required maxlength="200" placeholder="Nom du client, rue, village…"></label><label>Contact<input name="contact" maxlength="120"></label></div><label>Relevé, cotes et demandes du client<textarea name="notes" rows="6" maxlength="3000" placeholder="Ex. 45 m², ardoise souhaitée, gouttière à remplacer…"></textarea></label><label class="upload-field">📷 Ajouter des photos ou un croquis<input name="photos" type="file" accept="image/*" capture="environment" multiple></label><p class="help-line">Sur téléphone, l’icône photo ouvre l’appareil. Vous pourrez créer le devis complet à partir de ce relevé.</p><div class="modal-actions"><button class="btn primary">Enregistrer l’ébauche</button></div></form>`) }
function legacySaveQuoteDraft(event){event.preventDefault();const form=new FormData(event.target),place=String(form.get('place')||'').trim();if(!place)return;const files=form.getAll('photos').filter(file=>file?.name).map(file=>({name:file.name,url:file.size?URL.createObjectURL(file):''}));quoteDrafts.push({id:'draft-'+crypto.randomUUID(),place,contact:String(form.get('contact')||'').trim(),notes:String(form.get('notes')||'').trim(),photos:files,createdAt:new Date().toISOString()});closeModal();navigate('quotes');toast('Ébauche enregistrée. Vous pourrez créer le devis complet plus tard.')}
const quotesViewBeforeDrafts=quotesView;
quotesView=function(){return `<section class="field-action-strip"><div><p class="eyebrow">SUR LE TERRAIN</p><h2>Premier relevé</h2><span>Photos, croquis, cotes et demandes avant le devis complet.</span></div><button class="btn primary" onclick="quoteDraftForm()">+ Ébauche de devis</button></section>`+quotesViewBeforeDrafts()};
const snapshotBeforeQuoteDrafts=workspaceSnapshot;
workspaceSnapshot=function(){const state=JSON.parse(snapshotBeforeQuoteDrafts());state.quoteDrafts=quoteDrafts.filter(draft=>!draft.serverBacked).map(draft=>({...draft,photos:(draft.photos||[]).map(({url,...photo})=>photo)}));return JSON.stringify(state)};
const restoreBeforeQuoteDrafts=restoreWorkspace;
restoreWorkspace=function(state){restoreBeforeQuoteDrafts(state);quoteDrafts=Array.isArray(state.quoteDrafts)?state.quoteDrafts:[]};

let currentQuoteDraftSketches=[];
function quoteDraftForm(){currentQuoteDraftSketches=[];modal('Ébauche de devis',`<form onsubmit="saveQuoteDraft(event)"><p class="notice">Sur place : photos, croquis, cotes et demandes. Le devis complet se fera plus tard.</p><div class="form-two"><label>Client ou adresse<input name="place" required maxlength="200" placeholder="Nom du client, rue, village…"></label><label>Contact<input name="contact" maxlength="120"></label></div><label>Relevé, cotes et demandes<textarea name="notes" rows="5" maxlength="3000" placeholder="Ex. 45 m², ardoise souhaitée, gouttière à remplacer…"></textarea></label><div class="section-heading"><strong>Croquis</strong><span><button type="button" class="link" onclick="saveCurrentQuoteSketch()">Enregistrer ce croquis</button><button type="button" class="link" onclick="clearQuoteSketch()">Effacer</button></span></div><canvas id="quoteSketch" width="900" height="420" style="width:100%;height:210px;border:1px dashed #9aafa1;border-radius:8px;touch-action:none;background:#fff"></canvas><div id="quoteSketchList" class="help-line">Aucun croquis enregistré.</div><label class="upload-field">📷 Prendre ou ajouter une photo<input name="photos" type="file" accept="image/*" capture="environment" multiple></label><div class="modal-actions"><button class="btn primary">Enregistrer l’ébauche</button></div></form>`);initQuoteSketch()}
function initQuoteSketch(){const canvas=document.querySelector('#quoteSketch');if(!canvas||typeof canvas.getContext!=='function')return;const ctx=canvas.getContext('2d');ctx.lineWidth=4;ctx.lineCap='round';let drawing=false,last;const point=event=>{const rect=canvas.getBoundingClientRect(),scaleX=canvas.width/rect.width,scaleY=canvas.height/rect.height;return {x:(event.clientX-rect.left)*scaleX,y:(event.clientY-rect.top)*scaleY}};canvas.onpointerdown=event=>{drawing=true;canvas.dataset.dirty='true';last=point(event);canvas.setPointerCapture?.(event.pointerId)};canvas.onpointermove=event=>{if(!drawing)return;const next=point(event);ctx.beginPath();ctx.moveTo(last.x,last.y);ctx.lineTo(next.x,next.y);ctx.stroke();last=next};canvas.onpointerup=canvas.onpointercancel=()=>drawing=false}
function clearQuoteSketch(){const canvas=document.querySelector('#quoteSketch');if(canvas){canvas.getContext('2d').clearRect(0,0,canvas.width,canvas.height);canvas.dataset.dirty=''}}
function renderQuoteSketchList(){const node=document.querySelector('#quoteSketchList');if(node)node.innerHTML=currentQuoteDraftSketches.length?`${currentQuoteDraftSketches.length} croquis enregistré(s) · vous pouvez effacer la feuille et continuer.`:'Aucun croquis enregistré.'}
function saveCurrentQuoteSketch(){const canvas=document.querySelector('#quoteSketch');if(!canvas||canvas.dataset.dirty!=='true'){toast('Dessinez d’abord un croquis avant de l’enregistrer.');return false}currentQuoteDraftSketches.push({id:'sketch-'+crypto.randomUUID(),name:'Croquis '+(currentQuoteDraftSketches.length+1),data:canvas.toDataURL('image/png')});clearQuoteSketch();renderQuoteSketchList();toast('Croquis enregistré. Vous pouvez en faire un autre.');return true}
function saveQuoteDraft(event){event.preventDefault();const form=new FormData(event.target),place=String(form.get('place')||'').trim();if(!place)return;const canvas=document.querySelector('#quoteSketch');if(canvas?.dataset.dirty==='true')saveCurrentQuoteSketch();const files=form.getAll('photos').filter(file=>file?.name).map(file=>({name:file.name,url:file.size?URL.createObjectURL(file):''}));quoteDrafts.push({id:'draft-'+crypto.randomUUID(),place,contact:String(form.get('contact')||'').trim(),notes:String(form.get('notes')||'').trim(),sketches:[...currentQuoteDraftSketches],sketchData:currentQuoteDraftSketches[0]?.data||'',photos:files,createdAt:new Date().toISOString()});closeModal();navigate('quotes');toast('Ébauche, croquis et photos enregistrés.')}

function quoteDraftSketches(draft){return Array.isArray(draft.sketches)&&draft.sketches.length?draft.sketches:(draft.sketchData?[{id:'legacy-sketch',name:'Croquis',data:draft.sketchData}]:[])}
function quoteDraftFolders(){return quoteDrafts.length?`<section class="panel quote-draft-folders"><div class="panel-head"><div><p class="eyebrow">RELEVÉS TERRAIN</p><h2>Dossiers de visite</h2><span>Photos, croquis, cotes et demandes à reprendre avant le devis complet.</span></div><span class="badge">${quoteDrafts.length}</span></div><div class="album-grid">${quoteDrafts.map(draft=>{const sketches=quoteDraftSketches(draft),preview=safeImageUrl(sketches[0]?.data||'');return `<button class="album-card" onclick="openQuoteDraftFolder('${jsString(draft.id)}')">${preview?`<img src="${esc(preview)}" alt="${esc(sketches[0].name)}">`:''}<strong>${esc(draft.place)}</strong><small>${fullDate(draft.createdAt.slice(0,10))} · ${sketches.length} croquis · ${(draft.photos||[]).length} photo(s)</small></button>`}).join('')}</div></section>`:''}
function openQuoteDraftFolder(id){const draft=quoteDrafts.find(item=>item.id===id);if(!draft)return;const sketches=quoteDraftSketches(draft),photos=draft.photos||[];modal('Relevé terrain · '+draft.place,`<section class="worker-sheet"><div><p class="eyebrow">DOSSIER AVANT DEVIS</p><h2>${esc(draft.place)}</h2><p>${esc(draft.contact||'Contact à préciser')}</p></div><div class="notice"><strong>Notes de la visite</strong><br>${esc(draft.notes||'Aucune note saisie.').replace(/\n/g,'<br>')}</div><section><h3>Croquis</h3><div class="photo-picker">${sketches.map(sketch=>{const src=safeImageUrl(sketch.data||'');return src?`<figure><img src="${esc(src)}" alt="${esc(sketch.name)}"><figcaption>${esc(sketch.name)}</figcaption></figure>`:'<span class="badge">Croquis ignoré : format non autorisé</span>'}).join('')||'<p class="empty">Aucun croquis enregistré.</p>'}</div></section><section><h3>Photos ajoutées</h3>${photos.length?`<div class="photo-picker">${photos.map(photo=>{const src=safeImageUrl(photo.url||'');return src?`<figure><img src="${esc(src)}" alt="${esc(photo.name)}"><figcaption>${esc(photo.name)}</figcaption></figure>`:`<span class="badge">${esc(photo.name)}</span>`}).join('')}</div>`:'<p class="empty">Aucune photo ajoutée.</p>'}</section></section><div class="modal-actions"><button class="btn" onclick="closeModal();navigate('quotes')">Retour aux devis</button><button class="btn primary" onclick="quoteFormFromDraft('${jsString(draft.id)}')">Créer le devis complet</button></div>`) }
const quoteFormBeforeDraftFolder=quoteForm;
quoteForm=function(id,draftId=''){quoteFormBeforeDraftFolder(id);const draft=quoteDrafts.find(item=>item.id===draftId),form=document.querySelector('#modalbody form');if(!draft||!form)return;const put=(name,value)=>{const field=form.querySelector(`[name="${name}"]`);if(field)field.value=value};put('client',draft.contact||draft.place);put('clientAddress',draft.place);put('title','Devis à établir · '+draft.place);put('notes',[form.querySelector('[name="notes"]')?.value||'',`Relevé terrain : ${draft.notes||'voir dossier de visite.'}`].filter(Boolean).join('\n\n'));const marker=document.createElement('input');marker.type='hidden';marker.name='sourceDraftId';marker.value=draft.id;form.append(marker)};
function quoteFormFromDraft(id){closeModal();quoteForm(0,id);toast('Le relevé terrain est repris dans le nouveau devis.')}
const quotesViewBeforeDraftFolders=quotesView;
quotesView=function(){return quoteDraftFolders()+quotesViewBeforeDraftFolders()};

const actionsBeforeWorkerAlert=actions;
actions=function(){return actionsBeforeWorkerAlert()+(canFieldAction('manageAlerts')?`<section class="panel worker-alert-shortcut"><div><p class="eyebrow">OUTIL DU PATRON</p><h2>Créer une alerte à un ouvrier</h2><p>Choisissez une ou plusieurs personnes. Elles retrouveront directement le message dans « Mon espace › Mes alertes ».</p></div><button class="btn primary" onclick="workerAlertForm()">+ Créer une alerte</button></section>`:'')}
const requestedNavigation=['home','planning','personal','people','fleet','messages','gallery','jobs','quotes','accounting','actions','documents','permissions','company'];
tabs2.sort((a,b)=>requestedNavigation.indexOf(a[0])-requestedNavigation.indexOf(b[0]));

// Une fiche d'exécution partagée avec l'équipe ne reprend jamais les prix du devis client.
const showQuoteBeforeTeamDispatch=showQuote;
showQuote=function(id){showQuoteBeforeTeamDispatch(id);const actions=document.querySelector('#modalbody .modal-actions');if(actions&&!actions.querySelector('.send-worker-quote'))actions.insertAdjacentHTML('afterbegin',`<button class="btn send-worker-quote" onclick="quoteTeamDispatchForm(${id})">Envoyer à une équipe</button>`)};
function quoteTeamDispatchForm(id){const quote=quotes.find(item=>item.id===id),job=jobs.find(item=>item.id===quote?.job);if(!quote)return;const defaultTeam=teams.find(team=>team.id===(job?.timeEntries?.[0]?.team||job?.team))?.id||teams[0]?.id||'';modal('Envoyer la fiche à une équipe',`<form onsubmit="sendQuoteToTeam(event,${id})"><p class="notice"><strong>La fiche envoyée est sans prix.</strong> Elle reprend les travaux, quantités, cotes et la remarque terrain.</p><label>Équipe<select name="team">${teams.map(team=>`<option value="${team.id}" ${team.id===defaultTeam?'selected':''}>${esc(team.name)} · ${team.members.length} personne(s)</option>`).join('')}</select></label><label>Remarque pour l’équipe<textarea name="message" rows="4" maxlength="1000" placeholder="Ex. Vérifier les mesures avant commande.">${esc(quote.teamNote||'')}</textarea></label><div class="modal-actions"><button type="button" class="btn" onclick="showQuote(${id})">Annuler</button><button class="btn primary">Envoyer la fiche sans prix</button></div></form>`) }
function sendQuoteToTeam(event,id){event.preventDefault();const quote=quotes.find(item=>item.id===id),form=new FormData(event.target),team=teams.find(item=>String(item.id)===String(form.get('team')));if(!quote||!team)return;quote.teamNote=String(form.get('message')||'').trim();const job=jobs.find(item=>item.id===quote.job),recipientIds=[...new Set(team.members)],recipientNames=recipientIds.map(personId=>getPerson(personId)?.name).filter(Boolean);reminders.push({id:'quote-team-'+crypto.randomUUID(),title:'Fiche sans prix · '+quote.ref,date:reference,kind:'Chantier',owner:team.name,recipientIds,recipientNames,note:quote.teamNote||'Fiche d’exécution disponible dans le devis.',linkType:'job',linkId:quote.job,state:'todo',completedAt:'',quoteId:quote.id});closeModal();render();toast(`Fiche sans prix envoyée à ${team.name}.`)}
const showWorkerQuoteBeforeTeamNote=showWorkerQuote;
showWorkerQuote=function(id){showWorkerQuoteBeforeTeamNote(id);const sheet=document.querySelector('#modalbody .worker-sheet'),actions=document.querySelector('#modalbody .modal-actions'),quote=quotes.find(item=>item.id===id);if(sheet&&quote?.teamNote&&!sheet.querySelector('.team-note'))sheet.insertAdjacentHTML('beforeend',`<div class="notice team-note"><strong>Remarque terrain</strong><br>${esc(quote.teamNote)}</div>`);if(actions&&!actions.querySelector('.edit-team-note'))actions.insertAdjacentHTML('afterbegin',`<button class="btn edit-team-note" onclick="quoteTeamNoteForm(${id})">${quote?.teamNote?'Modifier la remarque':'Ajouter une remarque'}</button>`)};
function quoteTeamNoteForm(id){const quote=quotes.find(item=>item.id===id);if(!quote)return;modal('Remarque pour l’équipe',`<form onsubmit="saveQuoteTeamNote(event,${id})"><label>Message visible dans la fiche sans prix<textarea name="teamNote" rows="6" maxlength="1000" placeholder="Ex. Confirmer les cotes avant de commander.">${esc(quote.teamNote||'')}</textarea></label><p class="notice">Cette remarque est destinée à l’équipe ; elle ne modifie pas les conditions ni le prix du devis client.</p><div class="modal-actions"><button type="button" class="btn" onclick="showWorkerQuote(${id})">Annuler</button><button class="btn primary">Enregistrer la remarque</button></div></form>`) }
function saveQuoteTeamNote(event,id){event.preventDefault();const quote=quotes.find(item=>item.id===id);if(!quote)return;quote.teamNote=String(new FormData(event.target).get('teamNote')||'').trim();showWorkerQuote(id);toast('Remarque terrain enregistrée.')}

// Les petites réparations ne demandent pas toujours un devis complet : une mission suffit.
let repairMissions=[];
function missionForm(){const workers=activePeople().filter(person=>['Ouvrier','Apprenti','Stagiaire','Intérimaire'].includes(person.category));modal('Créer une mission',`<form onsubmit="saveRepairMission(event)"><p class="notice">Pour un dépannage ou une petite réparation : choisissez directement les personnes, sans devoir créer une équipe.</p><div class="form-two"><label>Client ou adresse<input name="place" required maxlength="200" placeholder="Client, adresse, lieu…"></label><label>Date souhaitée<input name="date" type="date" required value="${reference}"></label><label>Chantier existant <span class="subtle">(facultatif)</span><select name="job"><option value="">Aucun · intervention ponctuelle</option>${activeJobsForPlanning().map(job=>`<option value="${job.id}">${esc(job.name)}</option>`).join('')}</select></label><label>Objet de la mission<input name="title" required maxlength="150" placeholder="Ex. Réparation après infiltration"></label></div><label>Personnes à envoyer</label><div class="check-people compact-recipients">${workers.map(person=>`<label><input type="checkbox" name="recipient" value="${person.id}">${face(person)}<span><strong>${esc(person.name)}</strong><small>${esc(person.role)}</small></span></label>`).join('')}</div><label>Travail à effectuer<textarea name="work" rows="5" required maxlength="2000" placeholder="Décrire le problème, les vérifications et les travaux attendus…"></textarea></label><label class="upload-field">📷 Ajouter des photos<input name="photos" type="file" accept="image/*" multiple></label><p class="help-line">Les photos servent de repère à l’équipe. Elles seront stockées durablement lorsque le stockage documentaire sera connecté.</p><p id="missionError" class="form-error"></p><div class="modal-actions"><button class="btn primary">Créer et envoyer la mission</button></div></form>`) }
function saveRepairMission(event){event.preventDefault();const form=new FormData(event.target),recipientIds=[...new Set(form.getAll('recipient').map(Number))],place=String(form.get('place')||'').trim(),title=String(form.get('title')||'').trim(),work=String(form.get('work')||'').trim();if(!recipientIds.length){document.querySelector('#missionError').textContent='Cochez au moins une personne.';return}if(!place||!title||!work)return;const files=form.getAll('photos').filter(file=>file?.name).map(file=>({name:file.name,url:file.size?URL.createObjectURL(file):''})),jobId=Number(form.get('job')||0),recipientNames=recipientIds.map(id=>getPerson(id)?.name).filter(Boolean),mission={id:'mission-'+crypto.randomUUID(),place,date:form.get('date'),jobId,title,work,recipientIds,recipientNames,photos:files,createdAt:new Date().toISOString(),status:'Envoyée'};repairMissions.unshift(mission);reminders.push({id:'mission-alert-'+crypto.randomUUID(),title:'Mission · '+title,date:mission.date,kind:'Chantier',owner:recipientNames.join(', '),recipientIds,recipientNames,note:work,linkType:jobId?'job':'company',linkId:jobId,state:'todo',completedAt:'',missionId:mission.id});closeModal();render();toast(`Mission envoyée à ${recipientIds.length} personne(s).`)}
function repairMissionList(){return repairMissions.length?`<section class="panel"><div class="panel-head"><div><p class="eyebrow">INTERVENTIONS RAPIDES</p><h2>Missions envoyées</h2></div><span class="badge">${repairMissions.length}</span></div><div class="data-table"><table><thead><tr><th>Date</th><th>Mission</th><th>Lieu</th><th>Personnes</th><th>Photos</th><th>État</th></tr></thead><tbody>${repairMissions.map(mission=>`<tr><td>${fullDate(mission.date)}</td><td><strong>${esc(mission.title)}</strong><small>${esc(mission.work)}</small></td><td>${esc(mission.place)}</td><td>${esc(mission.recipientNames.join(', '))}</td><td>${mission.photos.length?`${mission.photos.length} ajoutée(s)`:'—'}</td><td><span class="badge green">${esc(mission.status)}</span></td></tr>`).join('')}</tbody></table></div></section>`:''}
const quotesViewBeforeRepairMissions=quotesView;
quotesView=function(){return `<section class="field-action-strip"><div><p class="eyebrow">DÉPANNAGES & PETITES RÉPARATIONS</p><h2>Mission rapide</h2><span>Choisissez les personnes, décrivez le travail et ajoutez les photos utiles.</span></div><button class="btn primary" onclick="missionForm()">+ Créer une mission</button></section>`+repairMissionList()+quotesViewBeforeRepairMissions()};
const snapshotBeforeRepairMissions=workspaceSnapshot;
workspaceSnapshot=function(){const state=JSON.parse(snapshotBeforeRepairMissions());state.repairMissions=repairMissions.map(mission=>({...mission,photos:mission.photos.map(({url,...photo})=>photo)}));return JSON.stringify(state)};
const restoreBeforeRepairMissions=restoreWorkspace;
restoreWorkspace=function(state){restoreBeforeRepairMissions(state);repairMissions=Array.isArray(state.repairMissions)?state.repairMissions:[]};

// Toute valeur « autre » reste saisissable : aucune liste ne bloque l'entreprise.
expenseReceiptForm=function(){if(!requireField('submitExpense','Vous ne pouvez pas déposer de dépense.'))return;modal('Déposer un ticket ou une facture',`<form onsubmit="saveExpenseReceipt(event)"><div class="form-two"><label>Date<input name="date" type="date" required value="${reference}"></label><label>Catégorie<select name="category" onchange="toggleOtherChoice(this,'expenseReceiptCategoryCustom')"><option>Matériaux</option><option>Restaurant / repas</option><option>Outillage</option><option>Carburant</option><option>Parking / déplacement</option><option>Autre dépense</option></select></label><label id="expenseReceiptCategoryCustom" hidden>Précisez la catégorie<input name="customCategory" maxlength="80" placeholder="Ex. assurance, petit outillage…"></label><label>Montant TVAC (€)<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Chantier lié<select name="job"><option value="0">Aucun / frais généraux</option>${activeJobsForPlanning().map(job=>`<option value="${job.id}">${esc(job.name)}</option>`).join('')}</select></label></div><label>Commerce / fournisseur<input name="supplier" required maxlength="120"></label><label>Photo du ticket ou de la facture<input name="file" type="file" accept="image/*,application/pdf" capture="environment" required></label><label>Remarque<input name="note" maxlength="400"></label><p class="notice">La comptabilité retrouvera la pièce, son auteur, son chantier et son montant dans un seul registre.</p><div class="modal-actions"><button class="btn primary">Envoyer à la comptabilité</button></div></form>`) };
saveExpenseReceipt=function(event){event.preventDefault();if(!requireField('submitExpense','Vous ne pouvez pas déposer de dépense.'))return;const form=new FormData(event.target),file=form.get('file'),person=sessionPerson(),category=String(form.get('customCategory')||form.get('category')||'').trim();if(!file?.name||!category)return;accountingData.expenseReceipts.push({id:'expense-'+crypto.randomUUID(),date:form.get('date'),category,amount:+form.get('amount'),job:+form.get('job'),supplier:form.get('supplier').trim(),note:form.get('note').trim(),fileName:file.name,submittedBy:person?.name||company.manager||'Patron',submittedAt:new Date().toISOString(),status:'À vérifier'});closeModal();render();toast('Pièce envoyée à la comptabilité.')};
